/* Fonts: one variable font (wght 300-900) split like Google Fonts does it.
   latin-ext (Polish letters) only downloads when such a character is on the page. */
@font-face {
  font-family: 'Red Hat Display';
  font-style: normal;
  font-weight: 300 900;
  font-display: swap;
  src: url('../assets/fonts/red-hat-display-latin-ext.woff2') format('woff2');
  unicode-range:
    U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329,
    U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F,
    U+A720-A7FF;
}

@font-face {
  font-family: 'Red Hat Display';
  font-style: normal;
  font-weight: 300 900;
  font-display: swap;
  src: url('../assets/fonts/red-hat-display-latin.woff2') format('woff2');
  unicode-range:
    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329,
    U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

/* Reset */
*,
*::before,
*::after {
  box-sizing: border-box;
}

* {
  margin: 0;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  min-height: 100svh;
  font-family: var(--ff);
  font-weight: var(--fw-medium);
  line-height: 1.2;
  color: var(--c-ink);
  background: var(--c-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img,
svg,
canvas {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

input,
button {
  font: inherit;
  color: inherit;
}

button {
  padding: 0;
  background: none;
  border: 0;
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

:where(ul, ol)[class] {
  padding: 0;
  list-style: none;
}

[hidden] {
  display: none !important;
}

/* Focus: white ring + dark halo, visible on both the dark hero and white sections. */
:focus-visible {
  outline: 2px solid var(--c-white);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px var(--c-black);
}

/* Layout */
.container {
  width: min(100% - 2 * var(--gutter), var(--container));
  margin-inline: auto;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* Button base. Hover colours change through an overlay's opacity (CLAUDE.md
   "Motion"); a variant sets --button-hover-bg to opt in. */
.button {
  position: relative;
  display: inline-flex;
  gap: 8px;
  align-items: center;
  justify-content: center;
  padding: 16px 24px;
  overflow: hidden;
  font-size: var(--fs-16);
  font-weight: var(--fw-bold);
  line-height: 1.2;
  white-space: nowrap;
  border-radius: var(--radius-pill);
  isolation: isolate;
}

.button::before {
  position: absolute;
  inset: 0;
  z-index: -1;
  content: '';
  background: var(--button-hover-bg, transparent);
  opacity: 0;
  transition: opacity var(--dur-button) var(--ease);
}

@media (hover: hover) {
  .button:hover::before {
    opacity: 1;
  }
}

.button:focus-visible::before {
  opacity: 1;
}

.button--primary {
  color: var(--c-ink);
  background: var(--c-yellow);
}

/* Reduced motion: transform amounts are neutralised in tokens.css; this stops
   any remaining keyframe animation. Opacity transitions are left as they are. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

