  gap: 8px;
  align-items: center;
  justify-content: center;
  padding: 16px 24px;
  overflow: hidden;
  font-size: var(--fs-16);
  font-weight: var(--fw-bold);
  line-height: 1.2;
  white-space: nowrap;
  border-radius: var(--radius-pill);
  isolation: isolate;
}

