/* Header (Figma 1:533, PLAN.md §0.3 / §3.2). Static layout only:
   hover overlay and burger panel come with the interaction step. */
.skip-link {
  position: absolute;
  top: 8px;
  left: 8px;
  z-index: 100;
  padding: 12px 16px;
  font-weight: var(--fw-bold);
  color: var(--c-ink);
  background: var(--c-white);
  border-radius: var(--radius-pill);
  transform: translateY(-200%);
}

.skip-link:focus-visible {
  transform: none;
}

.header {
  position: absolute;
  inset: 0 0 auto;
  z-index: 10;
  color: var(--c-white);
}

.header__inner {
  display: flex;
  gap: 8px;
  align-items: center;
  justify-content: space-between;
  width: min(100% - 2 * var(--gutter), var(--container));
  margin-inline: auto;
  padding-block: 16px;
}

.header__logo {
  display: flex;
  flex: none;
  align-items: center;
  height: 48px;
}

.header__actions {
  display: flex;
  flex: none;
  gap: 8px;
  align-items: center;
}

.header__icon,
.header__burger {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: var(--radius-pill);
}

.header__burger {
  align-content: center;
  gap: 5px;
}

.header__burger-line {
  display: block;
  width: 20px;
  height: 2px;
  background: currentcolor;
  border-radius: 1px;
}

/* Mobile first: logo, cart, burger. Nav, search, configurator and account
   move into the burger panel (interaction step). After the base rules above,
   so it wins over `.header__icon { display: grid }`. */
.header__nav,
.header__search,
.header__configurator,
.header__icon--user {
  display: none;
}

/* Full row from 1280 (burger below; design/NOTES.md). Below 1280 the row
   can't fit logo + 6 links + a usable search + actions. */
@media (width >= 1280px) {
  .header__inner {
    gap: clamp(16px, 3.33vw, 64px);
    justify-content: flex-start;
  }

  .header__nav,
  .header__icon--user {
    display: block;
  }

  .header__icon--user {
    display: grid;
  }

  .header__search,
  .header__configurator {
    display: flex;
  }

  .header__burger {
    display: none;
  }

  .header__links {
    display: flex;
    gap: clamp(12px, 1.67vw, 32px);
    align-items: center;
  }

  .header__link {
    display: inline-flex;
    gap: 4px;
    align-items: center;
    font-size: var(--fs-14);
    font-weight: var(--fw-bold);
    line-height: 1.2;
    white-space: nowrap;
  }

  .header__chevron {
    flex: none;
  }

  .search {
    flex: 1 1 0;
    gap: 16px;
    align-items: center;
    min-width: 0;
    padding: 15px 24px; /* + 1 px border = Figma 16 / 24 */
    border: 1px solid var(--c-line);
    border-radius: var(--radius-pill);
  }

  .search:focus-within {
    outline: 2px solid var(--c-white);
    outline-offset: 2px;
    box-shadow: 0 0 0 4px var(--c-black);
  }

  .search__input {
    flex: 1 1 auto;
    min-width: 0;
    padding: 0;
    font-size: var(--fs-14);
    font-weight: var(--fw-bold);
    line-height: 1.2;
    background: transparent;
    border: 0;
    appearance: none;
  }

  .search__input::placeholder {
    color: inherit;
    opacity: 1;
  }

  .search__input:focus-visible {
    outline: none;
    box-shadow: none;
  }

  .search__input::-webkit-search-cancel-button {
    display: none;
  }

  .search__button {
    display: grid;
    flex: none;
    place-items: center;
  }

  .header__configurator {
    gap: 9px;
    align-items: center;
    padding: 11px 16px;
    font-size: var(--fs-13);
    font-weight: var(--fw-bold);
    line-height: 1.1;
    white-space: nowrap;
    border-radius: var(--radius-pill);
  }

  .header__configurator svg {
    flex: none;
  }
}

/* 1280-1439: the configurator becomes icon-only (its label stays for screen
   readers) so the search pill keeps a usable width. */
@media (width >= 1280px) and (width < 1440px) {
  .header__configurator {
    padding: 14px;
  }

  .header__configurator-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

/* Hero (Figma 1:506, PLAN.md §0.3 / §3.3). Static: no slide animation yet.

   Two layouts share one rule: everything that must stay aligned with the photo
   (slide images and lamps) lives in a `.hero__stage` box with the photo's
   1920:1080 ratio, positioned identically.

   - Cover mode (landscape): the stage covers the hero like object-fit: cover.
   - Contained mode (portrait, max-aspect-ratio 5/4): covering would crop the
     lamps, so the stage is sized so the lamp group fits the viewport width and
     sits at the bottom. Above it, the slide's own sky colour (sampled from the
     photo's top edge) continues the image; the stage's top edge fades into it. */
.hero {
  --hero-h: clamp(560px, 100svh, 1080px);
  --stage-w: max(100%, var(--hero-h) * 16 / 9);
  --stage-h: calc(var(--stage-w) * 9 / 16);

  position: relative;
  display: grid;
  height: var(--hero-h);
  overflow: hidden;
  color: var(--c-white);
  background: var(--c-black);
}

.hero__slides {
  position: absolute;
  inset: 0;
}

.hero__slide {
  position: absolute;
  inset: 0;
  opacity: 0;
}

.hero__slide--active {
  opacity: 1;
}

/* Top-edge colour of each photo; scrim keeps white text >= 4.5:1 on mobile */
.hero__slide--rock {
  --hero-sky: #9c6744;
  --hero-scrim: 0%;
}

.hero__slide--interior {
  --hero-sky: #c5afa3;
  --hero-scrim: 45%;
}

.hero__stage {
  position: absolute;
  top: 50%;
  left: 50%;
  width: var(--stage-w);
  height: var(--stage-h);
  transform: translate(-50%, -50%);
}

.hero__img {
  width: 100%;
  height: 100%;
}

/* Lamps */
.hero__stage--lamps {
  z-index: 1;
}

.lamp {
  position: absolute;
  top: var(--y);
  left: var(--x);
  width: var(--w);
}

.lamp__img {
  width: 100%;
}

/* Text block: grid item on top of the absolute layers */
.hero__content {
  z-index: 2;
  grid-area: 1 / 1;
  align-self: center;
  width: min(100% - 2 * var(--gutter), var(--container));
  margin-inline: auto;
  padding-block: 64px;
  pointer-events: none;
}

.hero__inner {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.hero__inner > * {
  pointer-events: auto;
}

.hero__eyebrow {
  font-size: var(--fs-16);
  font-weight: var(--fw-medium);
  line-height: 1.2;
}

.hero__title {
  margin-top: 16px;
  font-size: var(--fs-hero);
  font-weight: var(--fw-bold);
  line-height: 1;
}

.hero__cta {
  margin-top: 32px;
}

/* Trustmate badge: bottom right of the hero on desktop (absolute against
   .hero, since .hero__content is not positioned), in the text flow on mobile. */
.hero__badge {
  display: inline-flex;
  gap: 12px;
  align-items: center;
  margin-top: 24px;
  padding: 12px 24px;
  font-size: var(--fs-13);
  font-weight: var(--fw-medium);
  line-height: 1.1;
  white-space: nowrap;
  background: var(--c-badge-bg);
  border-radius: var(--radius-pill);
}

.hero__rating {
  display: inline-flex;
  gap: 2px;
  align-items: center;
  font-size: var(--fs-21);
  font-weight: var(--fw-bold);
}

/* Arrows: hidden below 1024 (PLAN.md §5, proposed) */
.hero__arrow {
  position: absolute;
  top: 50%;
  z-index: 3;
  display: none;
  place-items: center;
  width: 48px;
  height: 48px;
  color: var(--c-line);
  background: var(--c-control-bg);
  border-radius: var(--radius-pill);
  transform: translateY(-50%);
}

.hero__arrow--prev {
  left: 72px;
}

.hero__arrow--next {
  right: 72px;
}

/* Progress: 2 x 64 x 2 px bars; the buttons are 44 px tall tap targets. */
.hero__progress {
  position: absolute;
  bottom: 11px; /* 32 px to the bar = 11 + (44 - 2) / 2 */
  left: 50%;
  z-index: 3;
  display: flex;
  gap: 4px;
  transform: translateX(-50%);
}

.hero__dot {
  position: relative;
  width: 64px;
  height: 44px;
}

.hero__dot::before,
.hero__dot-fill {
  position: absolute;
  inset: 21px 0;
}

.hero__dot::before {
  content: '';
  background: var(--c-track);
}

.hero__dot-fill {
  background: var(--c-yellow);
  transform: scaleX(0);
  transform-origin: left;
}

.hero__dot--active .hero__dot-fill {
  transform: scaleX(1);
}

@media (width >= 1024px) {
  .hero__arrow {
    display: grid;
  }

  .hero__badge {
    position: absolute;
    right: 72px;
    bottom: 32px;
    z-index: 3;
    margin: 0;
  }
}

/* Contained mode: portrait screens */
@media (max-aspect-ratio: 5/4) {
  .hero {
    --stage-w: calc((100vw - 2 * var(--gutter)) / var(--lamps-span));

    height: auto;
    min-height: var(--hero-h);
  }

  .hero__slide {
    background: var(--hero-sky);
  }

  .hero__slide::after {
    position: absolute;
    inset: 0 0 auto;
    height: calc(100% - var(--stage-h) * 0.8);
    content: '';
    background: linear-gradient(rgb(16 16 17 / var(--hero-scrim)) 60%, rgb(16 16 17 / 0%));
  }

  .hero__stage {
    top: auto;
    bottom: 0;

    /* centre the lamp group, not the photo */
    left: calc(50% - var(--stage-w) * var(--lamps-center));
    transform: none;
  }

  .hero__img {
    mask-image: linear-gradient(transparent, #000 25%);
  }

  .hero__content {
    align-self: start;

    /* room for the header on top and for the stage below; the stage's top
       8 % is sky, so the text may overlap that */
    padding-top: calc(var(--header-h) + 24px);
    padding-bottom: calc(var(--stage-h) * 0.92 + 24px);
  }
}

// Minimal static server for the done-check (node built-ins only).
import http from 'node:http';
import { readFile } from 'node:fs/promises';
import path from 'node:path';

const root = path.resolve(process.argv[2]);
const port = Number(process.argv[3] || 8765);
const types = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css',
  '.js': 'text/javascript',
  '.svg': 'image/svg+xml',
  '.webp': 'image/webp',
  '.png': 'image/png',
  '.woff2': 'font/woff2',
  '.json': 'application/json',
};

http
  .createServer(async (req, res) => {
    const url = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    const file = path.join(root, url.endsWith('/') ? url + 'index.html' : url);
    if (!file.startsWith(root)) return res.writeHead(403).end();
    try {
      const body = await readFile(file);
      res.writeHead(200, { 'Content-Type': types[path.extname(file)] || 'application/octet-stream' });
      res.end(body);
    } catch {
      res.writeHead(404).end('not found');
    }
  })
  .listen(port, '127.0.0.1', () => console.log(`serving ${root} on http://127.0.0.1:${port}`));

