async () => {
  const sizes = [[1024,700],[1279,633],[1280,633],[1280,800],[1366,657],[1439,789],[1440,789],[1440,900],[1536,730],[1920,1080],[768,1024],[375,812]];
  const out = [];
  const r = el => el && el.getBoundingClientRect();
  for (const [w,h] of sizes) {
    const f = document.createElement('iframe');
    f.style.cssText = `position:fixed;left:0;top:0;width:${w}px;height:${h}px;border:0;visibility:hidden`;
    f.src = '/'; document.body.append(f);
    await new Promise(res => f.onload = res);
    await f.contentDocument.fonts.ready;
    const d = f.contentDocument, q = s => d.querySelector(s);
    const prev = r(q('.hero__arrow--prev')), next = r(q('.hero__arrow--next'));
    const texts = ['.hero__eyebrow','.hero__title','.hero__cta','.hero__badge'].map(s => r(q(s)));
    const textL = Math.min(...texts.map(t=>t.left)), textR = Math.max(...[texts[0],texts[1],texts[2]].map(t=>t.right));
    const arrowsShown = prev.width > 0;
    const hit = arrowsShown && texts.some(t => !(t.right <= prev.left || t.left >= prev.right || t.bottom <= prev.top || t.top >= prev.bottom) || !(t.right <= next.left || t.left >= next.right || t.bottom <= next.top || t.top >= next.bottom));
    const cfg = r(q('.header__configurator')), user = r(q('.header__icon--user')), cart = r(q('.header__icon:not(.header__icon--user)'));
    const cfgSvg = r(q('.header__configurator svg')), userSvg = r(q('.header__icon--user svg'));
    const badge = r(q('.hero__badge')), prog = r(q('.hero__progress'));
    out.push({ w, h, overflowX: d.documentElement.scrollWidth - w,
      arrows: arrowsShown ? `${prev.left}-${prev.right}` : 'hidden',
      textLeft: Math.round(textL), gapToArrow: arrowsShown ? Math.round(textL - prev.right) : null, overlap: hit,
      cfg: cfg.width ? `${Math.round(cfg.width)}x${Math.round(cfg.height)} svg ${Math.round(cfgSvg.width)}` : 'hidden',
      user: user.width ? `${Math.round(user.width)}x${Math.round(user.height)} svg ${Math.round(userSvg.width)}` : 'hidden',
      cart: `${Math.round(cart.width)}x${Math.round(cart.height)}`,
      headerRowRight: Math.round(r(q('.header__inner')).right),
      badgeVsProgress: Math.round(badge.left - prog.right),
      textBottom: Math.round(Math.max(...texts.map(t=>t.bottom))), heroH: Math.round(r(q('.hero')).height) });
    f.remove();
  }
  return out;
}

