async (page) => {
  const browser = page.context().browser();
  const run = async ({ dpr = 1.5, w = 1280, h = 633, heroSrc = null, nudge = null, shot = null }) => {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: dpr });
    const p = await ctx.newPage();
    await p.goto('http://127.0.0.1:8765/');
    await p.evaluate(async ({ heroSrc, nudge }) => {
      const img = document.querySelector('.hero__slide--rock .hero__img');
      if (heroSrc) { img.removeAttribute('srcset'); img.src = heroSrc; }
      document.querySelectorAll('.lamp__img').forEach(i => i.style.mixBlendMode = 'difference');
      document.querySelector('.hero__stage--lamps').style.zIndex = 'auto';
      if (nudge) document.querySelectorAll('.lamp').forEach(l => l.style.translate = nudge);
      document.querySelector('.hero__content').style.visibility = 'hidden';
      await Promise.all([...document.images].map(i => i.decode().catch(() => {})));
    }, { heroSrc, nudge });
    await p.waitForTimeout(300);
    const info = await p.evaluate(() => {
      const r = e => { const b = e.getBoundingClientRect(); return [b.left, b.top, b.width, b.height].map(v => +v.toFixed(3)); };
      return {
        hero: document.querySelector('.hero__slide--rock .hero__img').currentSrc.split('/').pop(),
        heroRect: r(document.querySelector('.hero__slide--rock .hero__img')),
        lamps: [...document.querySelectorAll('.lamp__img')].map(i => ({ src: i.currentSrc.split('/').pop(), rect: r(i) })),
      };
    });
    const buf = await p.screenshot({ scale: 'device', path: shot || undefined });
    // mean difference inside each lamp's alpha (computed in page from the screenshot)
    const scores = await p.evaluate(async ({ b64, dpr }) => {
      const load = src => new Promise(res => { const i = new Image(); i.onload = () => res(i); i.src = src; });
      const s = await load('data:image/png;base64,' + b64);
      const out = [];
      for (const li of document.querySelectorAll('.lamp__img')) {
        const b = li.getBoundingClientRect();
        const x = Math.round(b.left * dpr), y = Math.round(b.top * dpr), W = Math.round(b.width * dpr), H = Math.round(b.height * dpr);
        const c = new OffscreenCanvas(W, H), g = c.getContext('2d');
        g.drawImage(s, -x, -y);
        const d = g.getImageData(0, 0, W, H).data;
        const m = new OffscreenCanvas(W, H), mg = m.getContext('2d');
        const lamp = await load(li.currentSrc); mg.drawImage(lamp, 0, 0, W, H);
        const a = mg.getImageData(0, 0, W, H).data;
        let sum = 0, n = 0, edge = 0, en = 0;
        for (let k = 0; k < d.length; k += 4) {
          const al = a[k + 3];
          if (al > 250) { sum += (d[k] + d[k + 1] + d[k + 2]) / 3; n++; }
          else if (al > 20) { edge += (d[k] + d[k + 1] + d[k + 2]) / 3; en++; }
        }
        out.push({ inside: +(sum / n).toFixed(2), edge: +(edge / en).toFixed(2) });
      }
      return out;
    }, { b64: buf.toString('base64'), dpr });
    await ctx.close();
    return { dpr, w, h, heroSrc, nudge, ...info, scores };
  };
  const res = [];
  res.push(await run({ dpr: 1, shot: '.playwright-mcp/diff-dpr1.png' }));
  res.push(await run({ dpr: 1.5, shot: '.playwright-mcp/diff-dpr15.png' }));
  res.push(await run({ dpr: 1.5, heroSrc: 'assets/img/hero-rock-2880.webp' }));
  res.push(await run({ dpr: 1.5, heroSrc: 'assets/img/hero-rock-1440.webp' }));
  res.push(await run({ dpr: 1.5, h: 634 }));
  res.push(await run({ dpr: 1.5, h: 720 }));
  res.push(await run({ dpr: 2, h: 633 }));
  return res;
}

