await (async (page) => {
  const browser = page.context().browser();
  const run = async ({ dpr = 1.5, w = 1280, h = 633, heroSrc = null, nudge = null, save = null }) => {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: dpr });
    const p = await ctx.newPage();
    await p.goto('http://127.0.0.1:8765/');
    await p.evaluate(async ({ heroSrc, nudge }) => {
      const img = document.querySelector('.hero__slide--rock .hero__img');
      if (heroSrc) { img.removeAttribute('srcset'); img.src = heroSrc; }
      if (nudge) document.querySelectorAll('.lamp').forEach(l => l.style.translate = nudge);
      document.querySelector('.hero__content').style.visibility = 'hidden';
      await Promise.all([...document.images].map(i => i.decode().catch(() => {})));
    }, { heroSrc, nudge });
    await p.waitForTimeout(200);
    const info = await p.evaluate(() => ({
      hero: document.querySelector('.hero__slide--rock .hero__img').currentSrc.split('/').pop(),
      heroH: document.querySelector('.hero').getBoundingClientRect().height,
      stageTop: document.querySelector('.hero__stage--lamps').getBoundingClientRect().top,
    }));
    const on = (await p.screenshot({ scale: 'device' })).toString('base64');
    await p.evaluate(() => document.querySelector('.hero__stage--lamps').style.visibility = 'hidden');
    await p.waitForTimeout(100);
    const off = (await p.screenshot({ scale: 'device' })).toString('base64');
    const out = await p.evaluate(async ({ on, off, dpr, save, w }) => {
      const load = src => new Promise(r => { const i = new Image(); i.onload = () => r(i); i.src = src; });
      const [A, B] = await Promise.all([load('data:image/png;base64,' + on), load('data:image/png;base64,' + off)]);
      const W = A.width, H = A.height;
      const ga = new OffscreenCanvas(W, H).getContext('2d'); ga.drawImage(A, 0, 0);
      const gb = new OffscreenCanvas(W, H).getContext('2d'); gb.drawImage(B, 0, 0);
      const a = ga.getImageData(0, 0, W, H).data, b = gb.getImageData(0, 0, W, H).data;
      const out = [];
      for (const li of document.querySelectorAll('.lamp__img')) {
        const r = li.getBoundingClientRect();
        const x0 = Math.max(0, Math.floor(r.left * dpr)), y0 = Math.max(0, Math.floor(r.top * dpr));
        const x1 = Math.min(W, Math.ceil(r.right * dpr)), y1 = Math.min(H, Math.ceil(r.bottom * dpr));
        let s = 0, n = 0, big = 0;
        for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) {
          const k = (y * W + x) * 4, d = (Math.abs(a[k] - b[k]) + Math.abs(a[k + 1] - b[k + 1]) + Math.abs(a[k + 2] - b[k + 2])) / 3;
          s += d; n++; if (d > 24) big++;
        }
        out.push({ mean: +(s / n).toFixed(2), over24: big });
      }
      if (save) {
        const diff = new ImageData(W, H);
        for (let k = 0; k < a.length; k += 4) { for (let c = 0; c < 3; c++) diff.data[k + c] = Math.min(255, Math.abs(a[k + c] - b[k + c]) * 4); diff.data[k + 3] = 255; }
        const c = document.createElement('canvas'); c.width = W; c.height = H; c.getContext('2d').putImageData(diff, 0, 0);
        c.style.cssText = `position:fixed;inset:0;width:${w}px;z-index:9999`; document.body.append(c);
      }
      return out;
    }, { on, off, dpr, save, w });
    if (save) await p.screenshot({ scale: 'device', path: save });
    await ctx.close();
    return JSON.stringify({ dpr, w, h, heroSrc, nudge, ...info, lamps: out });
  };
  const r = [];
  r.push(await run({ dpr: 1, save: '.playwright-mcp/diff-1280-dpr1.png' }));
  r.push(await run({ dpr: 1.5, save: '.playwright-mcp/diff-1280-dpr15.png' }));
  r.push(await run({ dpr: 1.5, heroSrc: 'assets/img/hero-rock-1440.webp' }));
  r.push(await run({ dpr: 1.5, heroSrc: 'assets/img/hero-rock-2880.webp' }));
  r.push(await run({ dpr: 1.5, h: 634 }));
  r.push(await run({ dpr: 1.5, nudge: '0 -0.333px' }));
  r.push(await run({ dpr: 1.5, nudge: '0 0.333px' }));
  r.push(await run({ dpr: 1, w: 1920, h: 1080 }));
  return r.join('\n');
})(page);
