async (page) => {
  const browser = page.context().browser();
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 633 }, deviceScaleFactor: 1.5 });
  const p = await ctx.newPage();
  const errors = [];
  p.on('console', m => m.type() === 'error' && errors.push(m.text()));
  await p.goto('http://127.0.0.1:8765/');
  await p.evaluate(() => Promise.all([...document.images].map(i => i.decode().catch(() => {}))));
  await p.screenshot({ scale: 'css', path: '.playwright-mcp/hero-1280-dpr15-slide1.png' });
  await p.evaluate(() => {
    document.querySelector('.hero__slide--rock').classList.remove('hero__slide--active');
    document.querySelector('.hero__slide--interior').classList.add('hero__slide--active');
    document.querySelector('.hero__stage--lamps').classList.add('hero__stage--lamps-visible');
  });
  await p.waitForTimeout(900);
  await p.screenshot({ scale: 'css', path: '.playwright-mcp/hero-1280-dpr15-slide2.png' });
  const sweep = [];
  for (const [w, h] of [[320, 640], [375, 812], [768, 1024], [1024, 700], [1280, 633], [1440, 789], [1920, 1080], [2560, 1080]]) {
    await p.setViewportSize({ width: w, height: h });
    await p.waitForTimeout(50);
    sweep.push(await p.evaluate(() => {
      const s = document.querySelector('.hero__stage--lamps').getBoundingClientRect();
      const inView = [...document.querySelectorAll('.lamp')].every(l => { const b = l.getBoundingClientRect(); return b.left >= 0 && b.right <= innerWidth; });
      return `${innerWidth}x${innerHeight} overflowX ${document.documentElement.scrollWidth - document.documentElement.clientWidth} stage ${Math.round(s.width)}x${Math.round(s.height)} lampsInView ${inView}`;
    }));
  }
  await ctx.close();
  return sweep.join('\n') + '\nerrors: ' + JSON.stringify(errors);
}

