a {
  color: inherit;
  text-decoration: none;
}

:where(ul, ol)[class] {
  padding: 0;
  list-style: none;
}

[hidden] {
  display: none !important;
}

/* Focus: white ring + dark halo, visible on both the dark hero and white sections. */
:focus-visible {
  outline: 2px solid var(--c-white);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px var(--c-black);
}

/* Layout */
.container {
  width: min(100% - 2 * var(--gutter), var(--container));
  margin-inline: auto;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* Button base. Hover colours change through an overlay's opacity (CLAUDE.md
   "Motion"); a variant sets --button-hover-bg to opt in. */
.button {
  position: relative;
  display: inline-flex;
  gap: 8px;
  align-items: center;
  justify-content: center;
  padding: 16px 24px;
  overflow: hidden;
  font-size: var(--fs-16);
  font-weight: var(--fw-bold);
  line-height: 1.2;
  white-space: nowrap;
  border-radius: var(--radius-pill);
  isolation: isolate;
}

.button::before {
  position: absolute;
  inset: 0;
  z-index: -1;
  content: '';
  background: var(--button-hover-bg, transparent);
  opacity: 0;
  transition: opacity var(--dur-button) var(--ease);
}

@media (hover: hover) {
  .button:hover::before {
    opacity: 1;
  }
}

.button:focus-visible::before {
  opacity: 1;
}

.button--primary {
  color: var(--c-ink);
  background: var(--c-yellow);
}

/* Reduced motion: transform amounts are neutralised in tokens.css; this stops
   any remaining keyframe animation. Opacity transitions are left as they are. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

