        lamps.classList.toggle('hero__stage--lamps-visible', slides[index].hasAttribute('data-slide-lamps'));
      }
      renderProgress();
    }

    function tick(now) {
      frame = 0;
      // Clamp long gaps (throttled frames) so the bar never skips ahead.
      if (last !== null) elapsed += Math.min(now - last, 100);
      last = now;
      if (elapsed >= interval) show(index + 1);
      else renderProgress();
      update();
    }

    function update() {
      if (autoplay()) {
        if (!frame) frame = requestAnimationFrame(tick);
      } else {
        if (frame) cancelAnimationFrame(frame);
        frame = 0;
        last = null;
        renderProgress();
      }
    }

