async (page) => {
  const browser = page.context().browser();
  const out = [];
  for (const [w, h] of [[1280, 633], [1439, 789], [1440, 789], [1920, 1080]]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h } });
    const p = await ctx.newPage();
    const errs = []; p.on('console', m => m.type() === 'error' && errs.push(m.text())); p.on('pageerror', e => errs.push(String(e)));
    await p.goto('http://127.0.0.1:8765/');
    await p.mouse.move(w / 2, h / 2);
    const m = await p.evaluate(() => {
      const r = s => document.querySelector(s).getBoundingClientRect();
      return { search: Math.round(r('.search').width), searchH: Math.round(r('.search').height), userToCart: Math.round(r('.header__actions .header__icon').left - r('.header__icon--user').right),
        rowRight: Math.round(r('.header__actions').right), headerH: Math.round(r('.header').height), navLeft: Math.round(r('.header__nav').left),
        cfg: Math.round(r('.header__configurator').width), overflow: document.documentElement.scrollWidth - innerWidth };
    });
    await p.mouse.move(w / 2, 40);
    await p.waitForTimeout(400);
    const hov = await p.evaluate(() => ({ color: getComputedStyle(document.querySelector('.header__link')).color, bg: getComputedStyle(document.querySelector('.header'), '::before').opacity }));
    if (w === 1920) await p.screenshot({ path: '.playwright-mcp/header-hover-1920.png', clip: { x: 0, y: 0, width: 1920, height: 200 } });
    if (w === 1280) await p.screenshot({ path: '.playwright-mcp/header-hover-1280.png', clip: { x: 0, y: 0, width: 1280, height: 160 } });
    await p.mouse.move(w / 2, h / 2);
    await p.waitForTimeout(400);
    const left = await p.evaluate(() => ({ color: getComputedStyle(document.querySelector('.header__link')).color, bg: getComputedStyle(document.querySelector('.header'), '::before').opacity }));
    out.push(JSON.stringify({ w, h, ...m, hover: hov, afterLeave: left, errs }));
    await ctx.close();
  }
  return out.join('\n');
}

