### Ran Playwright code
```js
await (async (page) => {
  const browser = page.context().browser();
  const out = [];
  for (const [w, h] of [[375, 812], [768, 1024], [1279, 633]]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, hasTouch: w < 1000 });
    const p = await ctx.newPage();
    const errs = []; p.on('pageerror', e => errs.push(String(e)));
    await p.goto('http://127.0.0.1:8765/');
    const closed = await p.evaluate(() => ({ vis: getComputedStyle(document.querySelector('[data-menu]')).visibility, overflow: document.documentElement.scrollWidth - innerWidth }));
    await p.click('[data-menu-toggle]');
    await p.waitForTimeout(700);
    const opened = await p.evaluate(() => {
      const menu = document.querySelector('[data-menu]').getBoundingClientRect();
      return { expanded: document.querySelector('[data-menu-toggle]').getAttribute('aria-expanded'), focus: document.activeElement.textContent.trim().slice(0, 20),
        menu: [menu.left, menu.top, menu.width, menu.height].map(Math.round), mainInert: document.querySelector('main').inert,
        htmlOverflow: getComputedStyle(document.documentElement).overflow, overflowX: document.documentElement.scrollWidth - innerWidth,
        menuScroll: document.querySelector('[data-menu]').scrollHeight - document.querySelector('[data-menu]').clientHeight };
    });
    await p.screenshot({ path: `.playwright-mcp/menu-${w}.png` });
    // focus trap: tab through and record
    const seq = [];
    for (let i = 0; i < 16; i++) { await p.keyboard.press('Tab'); seq.push(await p.evaluate(() => (document.activeElement.getAttribute('aria-label') || document.activeElement.textContent || document.activeElement.placeholder || '').trim().slice(0, 14))); }
    const inHeader = await p.evaluate(() => document.querySelector('[data-header]').contains(document.activeElement));
    await p.keyboard.press('Escape');
    await p.waitForTimeout(700);
    const after = await p.evaluate(() => ({ expanded: document.querySelector('[data-menu-toggle]').getAttribute('aria-expanded'), focusIsToggle: document.activeElement.matches('[data-menu-toggle]'),
      vis: getComputedStyle(document.querySelector('[data-menu]')).visibility, mainInert: document.querySelector('main').inert }));
    out.push(JSON.stringify({ w, closed, opened, tabOrder: seq, stillInHeader: inHeader, afterEsc: after, errs }));
    // resize-to-desktop closes
    if (w === 1279) {
      await p.click('[data-menu-toggle]'); await p.waitForTimeout(100);
      await p.setViewportSize({ width: 1300, height: 633 }); await p.waitForTimeout(100);
      out.push('resize to 1300 -> ' + JSON.stringify(await p.evaluate(() => ({ open: document.querySelector('.header--open') !== null, mainInert: document.querySelector('main').inert }))));
    }
    await ctx.close();
  }
  return out.join('\n');
})(page);
```
