async (page) => {
  const browser = page.context().browser();
  const state = p => p.evaluate(() => {
    const act = [...document.querySelectorAll('[data-slide]')].findIndex(s => s.classList.contains('hero__slide--active'));
    const fills = [...document.querySelectorAll('.hero__dot-fill')].map(f => { const m = getComputedStyle(f).transform; return m === 'none' ? 'none' : +(+m.split('(')[1].split(',')[0]).toFixed(2); });
    return { slide: act + 1, lamps: document.querySelector('[data-lamps]').classList.contains('hero__stage--lamps-visible'),
      ariaHidden: [...document.querySelectorAll('[data-slide]')].map(s => s.getAttribute('aria-hidden')), current: [...document.querySelectorAll('[data-slider-dot]')].map(d => d.getAttribute('aria-current')), fills };
  });
  const log = [];
  // 1. autoplay timing
  let ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
  let p = await ctx.newPage();
  const errs = []; p.on('pageerror', e => errs.push(String(e)));
  await p.clock.install();
  await p.goto('http://127.0.0.1:8765/');
  await p.mouse.move(960, 700);
  log.push('t=0      ' + JSON.stringify(await state(p)));
  await p.clock.runFor(1500); log.push('t=1.5s   ' + JSON.stringify(await state(p)));
  await p.clock.runFor(1450); log.push('t=2.95s  ' + JSON.stringify(await state(p)));
  await p.clock.runFor(100); log.push('t=3.05s  ' + JSON.stringify(await state(p)));
  await p.clock.runFor(3000); log.push('t=6.05s  ' + JSON.stringify(await state(p)));
  // 2. hover on arrow pauses
  await p.clock.runFor(1000);
  await p.hover('[data-slider-next]');
  const before = await state(p);
  await p.clock.runFor(5000); log.push('hover next 5s: before ' + JSON.stringify(before.fills) + ' after ' + JSON.stringify(await state(p)));
  await p.mouse.move(960, 700);
  await p.clock.runFor(2100); log.push('leave +2.1s ' + JSON.stringify(await state(p)));
  // 3. clicks reset
  await p.click('[data-slider-next]'); await p.mouse.move(960, 700);
  log.push('click next ' + JSON.stringify(await state(p)));
  await p.click('[data-slider-dot]:nth-child(2)'); await p.mouse.move(960, 700);
  log.push('click dot2 ' + JSON.stringify(await state(p)));
  await p.click('[data-slider-prev]'); await p.mouse.move(960, 700);
  log.push('click prev ' + JSON.stringify(await state(p)));
  // mouse click shouldn't pause (no focus-visible)
  await p.clock.runFor(3100); log.push('after mouse click +3.1s ' + JSON.stringify(await state(p)));
  // 4. keyboard focus pauses; arrow keys
  await p.focus('[data-slider-next]');
  await p.keyboard.press('Tab'); await p.keyboard.press('Shift+Tab');
  const k0 = await state(p);
  await p.clock.runFor(6000); log.push('kbd focus 6s: ' + k0.slide + ' -> ' + (await state(p)).slide);
  await p.keyboard.press('ArrowRight'); log.push('ArrowRight ' + (await state(p)).slide);
  await p.keyboard.press('ArrowLeft'); log.push('ArrowLeft ' + (await state(p)).slide);
  log.push('errors ' + JSON.stringify(errs));
  await ctx.close();
  // 5. reduced motion: no autoplay, active bar full
  ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 }, reducedMotion: 'reduce' });
  p = await ctx.newPage();
  await p.clock.install();
  await p.goto('http://127.0.0.1:8765/');
