async (page) => {
  const browser = page.context().browser();
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 633 }, deviceScaleFactor: 1.5, reducedMotion: 'no-preference' });
  const p = await ctx.newPage();
  await p.goto('http://127.0.0.1:8765/');
  await p.evaluate(async () => {
    document.querySelectorAll('.hero__content,.hero__arrow,.hero__progress,.hero__badge,.header').forEach(e => e.style.visibility = 'hidden');
    await Promise.all([...document.images].map(i => i.decode().catch(() => {})));
  });
  await p.hover('.hero__progress'); // pause autoplay (hover on control)
  const rest = (await p.screenshot({ scale: 'device' })).toString('base64');
  const lampScore = (shot) => p.evaluate(async ({ shot, rest }) => {
    const load = src => new Promise(r => { const i = new Image(); i.onload = () => r(i); i.src = src; });
    const [A, B] = await Promise.all([load('data:image/png;base64,' + shot), load('data:image/png;base64,' + rest)]);
    const W = A.width, H = A.height, dpr = W / innerWidth;
    const ga = new OffscreenCanvas(W, H).getContext('2d'); ga.drawImage(A, 0, 0);
    const gb = new OffscreenCanvas(W, H).getContext('2d'); gb.drawImage(B, 0, 0);
    const a = ga.getImageData(0, 0, W, H).data, b = gb.getImageData(0, 0, W, H).data;
    return [...document.querySelectorAll('.lamp__img')].map(li => {
      const r = li.getBoundingClientRect(); let s = 0, n = 0;
      for (let y = Math.max(0, Math.floor(r.top * dpr)); y < Math.min(H, Math.ceil(r.bottom * dpr)); y++)
        for (let x = Math.floor(r.left * dpr); x < Math.ceil(r.right * dpr); x++) { const k = (y * W + x) * 4; s += (Math.abs(a[k] - b[k]) + Math.abs(a[k + 1] - b[k + 1]) + Math.abs(a[k + 2] - b[k + 2])) / 3; n++; }
      return +(s / n).toFixed(1);
    });
  }, { shot, rest });
  // seek helper: trigger, pause all transitions, set time
  const frame = async (dir, t, file) => {
    await p.evaluate(({ dir, t }) => {
      const go = dir === 'to2' ? 1 : 0;
      // instant reset to the opposite state first (no transitions)
      document.querySelectorAll('[data-slide]').forEach((s, i) => s.classList.toggle('hero__slide--active', i !== go));
      document.querySelector('[data-lamps]').classList.toggle('hero__stage--lamps-visible', go === 0);
      document.getAnimations().forEach(a => a.finish());
      document.body.offsetWidth;
      document.querySelectorAll('[data-slide]').forEach((s, i) => s.classList.toggle('hero__slide--active', i === go));
      document.querySelector('[data-lamps]').classList.toggle('hero__stage--lamps-visible', go === 1);
      document.body.offsetWidth;
      document.getAnimations().forEach(a => { a.pause(); a.currentTime = t; });
    }, { dir, t });
    const buf = await p.screenshot({ scale: 'device', path: file || undefined });
    return buf.toString('base64');
  };
  const out = [];
  for (const dir of ['to2', 'to1']) {
    for (const t of [0, 150, 300, 450, 600, 800, 1100, 1500]) {
      const save = (t === 300 || t === 1100) ? `.playwright-mcp/handoff-${dir}-${t}.png` : null;
      const shot = await frame(dir, t, save);
      out.push(`${dir} t=${t}ms  lamp-region diff vs slide-1 at rest: ${JSON.stringify(await lampScore(shot))}`);
    }
  }
  await ctx.close();
  return out.join('\n');
}

