async (page) => {
  const browser = page.context().browser();
  const log = [];
  const slide = p => p.evaluate(() => [...document.querySelectorAll('[data-slide]')].findIndex(s => s.classList.contains('hero__slide--active')) + 1);
  for (const [w, h] of [[375, 812], [1920, 1080]]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, hasTouch: w < 1024 });
    const p = await ctx.newPage();
    const errs = []; p.on('pageerror', e => errs.push(String(e)));
    await p.clock.install({ time: 0 }); await p.clock.pauseAt(1000);
    await p.goto('http://127.0.0.1:8765/');
    const geo = await p.evaluate(() => {
      const r = e => { const b = e.getBoundingClientRect(); return [Math.round(b.left), Math.round(b.top), Math.round(b.width), Math.round(b.height)]; };
      const dots = [...document.querySelectorAll('[data-slider-dot]')].map(r);
      const pause = document.querySelector('[data-slider-pause]');
      const badge = r(document.querySelector('.hero__badge'));
      return { dots, pause: r(pause), hidden: pause.hidden, label: pause.getAttribute('aria-label'), pressed: pause.getAttribute('aria-pressed'), badge, segmentsCentre: Math.round((dots[0][0] + dots[1][0] + dots[1][2]) / 2), vw: innerWidth };
    });
    log.push(`${w}: ${JSON.stringify(geo)}`);
    await p.screenshot({ path: `.playwright-mcp/pause-${w}.png`, clip: { x: Math.max(0, geo.segmentsCentre - 120), y: geo.dots[0][1] - 20, width: 240, height: 84 } });
    if (w === 1920) {
      // mouse: click pause -> stays on slide for 10 s; icon flips
      await p.click('[data-slider-pause]'); await p.mouse.move(960, 400);
      const pr = await p.getAttribute('[data-slider-pause]', 'aria-pressed');
      await p.clock.runFor(10000); log.push(`clicked pause: pressed=${pr}, after 10 s slide ${await slide(p)}`);
      await p.screenshot({ path: '.playwright-mcp/pause-1920-paused.png', clip: { x: geo.segmentsCentre - 120, y: geo.dots[0][1] - 20, width: 240, height: 84 } });
      await p.click('[data-slider-pause]'); await p.mouse.move(960, 400);
      await p.clock.runFor(3100); log.push(`clicked play: pressed=${await p.getAttribute('[data-slider-pause]', 'aria-pressed')}, +3.1 s slide ${await slide(p)}`);
      // keyboard: focus toggle with Tab-ish, press Space -> pause; press again -> plays even though focus stays inside
      await p.focus('[data-slider-pause]'); await p.keyboard.press('Shift+Tab'); await p.keyboard.press('Tab');
      await p.keyboard.press('Space');
      const s0 = await slide(p);
      await p.clock.runFor(6000); log.push(`kbd Space -> pressed=${await p.getAttribute('[data-slider-pause]', 'aria-pressed')}, 6 s: ${s0} -> ${await slide(p)}`);
      await p.keyboard.press('Space');
      await p.clock.runFor(3100); log.push(`kbd Space again (focus still on toggle) -> pressed=${await p.getAttribute('[data-slider-pause]', 'aria-pressed')}, +3.1 s: ${await slide(p)} (should differ from ${s0})`);
    }
    log.push('errors ' + JSON.stringify(errs));
    await ctx.close();
  }
  const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 }, reducedMotion: 'reduce' });
  const p = await ctx.newPage(); await p.goto('http://127.0.0.1:8765/');
  log.push('reduced motion: toggle hidden=' + await p.evaluate(() => document.querySelector('[data-slider-pause]').hidden));
  await ctx.close();
  return log.join('\n');
}

