  :root {
    /* No transforms (scale, movement). Opacity fades keep their durations. */
    --scale-tile-hover: 1;
    --scale-slide-in: 1;
    --move-menu: 0%;
    --dur-zoom: 0ms;
    --dur-move: 0ms;
  }
}

