  await p.goto('http://127.0.0.1:8765/');
  await p.evaluate(async () => { document.querySelectorAll('img[loading=lazy]').forEach(i => i.loading = 'eager'); await document.fonts.ready; await Promise.all([...document.images].map(i => i.decode().catch(() => {}))); });
  const m = await p.evaluate(() => {
    const vps = document.querySelector('.vps').getBoundingClientRect();
    const top = vps.top + scrollY;
    const r = (el) => { const b = el.getBoundingClientRect(); return [Math.round(b.left), Math.round(b.top + scrollY - top + 0) , Math.round(b.width), Math.round(b.height)]; };
    // section-relative: vps has padding-top 86 and starts at the section top
    return {
      vps: [Math.round(vps.left), Math.round(top), Math.round(vps.width), Math.round(vps.height)],
      benefits: [...document.querySelectorAll('.benefit')].map(r),
      benefitTitle: r(document.querySelector('.benefit__title')), benefitText: r(document.querySelector('.benefit__text')), icon: r(document.querySelector('.benefit__icon')),
      tiles: [...document.querySelectorAll('.tile')].map(r),
      tileText: [...document.querySelectorAll('.tile')].map(t => ({ eyebrow: r(t.querySelector('.tile__eyebrow')), title: r(t.querySelector('.tile__title')), btn: r(t.querySelector('.button')) })),
      imgs: [...document.querySelectorAll('.tile__img')].map(i => i.currentSrc.split('/').pop()),
      fonts: [getComputedStyle(document.querySelector('.benefit__title')).fontSize, getComputedStyle(document.querySelector('.tile__eyebrow')).fontSize, getComputedStyle(document.querySelector('.tile__title')).fontSize],
    };
  });
  // screenshot the section region (section = vps box) for comparison
  const sec = await p.evaluate(() => { const b = document.querySelector('.vps').getBoundingClientRect(); return { y: b.top + scrollY, h: b.height }; });
  await p.screenshot({ path: '.playwright-mcp/vps-1920.png', fullPage: true, clip: { x: 0, y: sec.y, width: 1920, height: Math.round(sec.h) } });
  // diff against the frame in-page
  const diff = await p.evaluate(async ({ y, h }) => {
    const load = s => new Promise(r => { const i = new Image(); i.onload = () => r(i); i.src = s; });
    const frame = await load('design/frames/vp.png');
    return { frame: [frame.naturalWidth, frame.naturalHeight] };
  }, sec);
  await ctx.close();
  return JSON.stringify({ m, sec, diff, errs });
})(page);
