async (page) => {
  const browser = page.context().browser();
  const out = [];
  for (const [w, h, dpr] of [[320, 640, 2], [375, 812, 3], [768, 1024, 2], [1023, 700, 1], [1024, 700, 1], [1280, 633, 1.5], [1440, 789, 1], [1920, 1080, 1]]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: dpr });
    const p = await ctx.newPage();
    const errs = []; p.on('console', m => m.type() === 'error' && !/404/.test(m.text()) && errs.push(m.text())); p.on('pageerror', e => errs.push(String(e)));
    await p.goto('http://127.0.0.1:8765/');
    await p.evaluate(async () => { document.querySelectorAll('img[loading=lazy]').forEach(i => i.loading = 'eager'); await document.fonts.ready; await Promise.all([...document.images].map(i => i.decode().catch(() => {}))); });
    const r = await p.evaluate((dpr) => {
      const R = e => e.getBoundingClientRect();
      const tiles = [...document.querySelectorAll('.tile')].map(t => {
        const img = t.querySelector('.tile__img'), b = R(t);
        // rendered (cover) image width
        const ar = img.naturalWidth / img.naturalHeight, rendered = Math.max(b.width, b.height * ar);
        const body = R(t.querySelector('.tile__body'));
        const title = t.querySelector('.tile__title');
        return { size: `${Math.round(b.width)}x${Math.round(b.height)}`, need: Math.round(rendered * dpr), got: img.currentSrc.split('-').pop().replace('.webp', ''),
          bodyFits: body.top >= b.top - 0.5, titleLines: Math.round(R(title).height / (parseFloat(getComputedStyle(title).fontSize) * 1.1)) };
      });
      const ben = [...document.querySelectorAll('.benefit')].map(R);
      const cols = new Set(ben.map(b => Math.round(b.top))).size;
      const textOverflow = [...document.querySelectorAll('.benefit__title, .tile__title, .tile__eyebrow, .button')].filter(e => e.scrollWidth > e.clientWidth + 1).map(e => e.textContent.trim().slice(0, 20));
      return { overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth, benefitRows: cols, benefitW: Math.round(ben[0].width), tiles, textOverflow };
    }, dpr);
    if ([375, 768, 1280].includes(w)) {
      const top = await p.evaluate(() => document.querySelector('.vps').getBoundingClientRect().top + scrollY);
      const hh = await p.evaluate(() => document.querySelector('.vps').getBoundingClientRect().height);
      await p.screenshot({ path: `.playwright-mcp/vps-${w}.png`, fullPage: true, clip: { x: 0, y: top, width: w, height: Math.min(hh, 4000) }, scale: 'css' });
    }
    out.push(JSON.stringify({ w, dpr, ...r, errs }));
    await ctx.close();
  }
  return out.join('\n');
}

