  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  height: clamp(440px, 60vw, 520px);
  overflow: hidden;
  color: var(--tile-fg);
  background: var(--tile-bg, var(--c-tile-stone));
  border-radius: 24px;
  isolation: isolate;
}

.tile--thoro {
  --tile-fg: var(--c-white);
  --tile-pos: 40% center;
}

.tile--configurator {
  --tile-fg: var(--c-white);
  --tile-bg: var(--c-tile-blue);
  --tile-pos: 85% center;
}

.tile--catalog {
  --tile-bg: var(--c-tile-cream);
  --tile-pos: 85% center;
