async (page) => {
  const browser = page.context().browser();
  const out = [];
  for (const [w, h] of [[320, 640], [375, 812], [768, 1024], [1023, 700], [1024, 700], [1100, 700], [1280, 633], [1440, 789], [1920, 1080], [2560, 1080]]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h } });
    const p = await ctx.newPage();
    await p.goto('http://127.0.0.1:8765/');
    const r = await p.evaluate(() => {
      const R = e => e.getBoundingClientRect();
      const t = [...document.querySelectorAll('.tile')].map(x => `${Math.round(R(x).width)}x${Math.round(R(x).height)}`);
      return { overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth, tiles: t.join(' '), rowWidth: Math.round(R(document.querySelectorAll('.tile')[1]).right - R(document.querySelectorAll('.tile')[0]).left) };
    });
    out.push(`${w}: ${JSON.stringify(r)}`);
    await ctx.close();
  }
  // hover / focus / reduced motion at 1440
  const run = async (opts) => {
    const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, ...opts });
    const p = await ctx.newPage();
    await p.goto('http://127.0.0.1:8765/');
    await p.evaluate(() => document.querySelector('.tile--catalog').scrollIntoView({ block: 'center' }));
    const st = () => p.evaluate(() => { const t = document.querySelector('.tile--catalog'); return { scale: getComputedStyle(t.querySelector('.tile__img')).scale, overlay: getComputedStyle(t.querySelector('.button'), '::before').opacity, cursor: getComputedStyle(t.querySelector('.tile__link'), '::after').cursor }; });
    const rest = await st();
    const box = await p.evaluate(() => { const b = document.querySelector('.tile--catalog').getBoundingClientRect(); return { x: b.left + b.width * 0.7, y: b.top + 40 }; });
    await p.mouse.move(box.x, box.y); await p.waitForTimeout(700);
    const hover = await st();
    // click on the image area goes to the link?
    const hit = await p.evaluate(({ x, y }) => document.elementFromPoint(x, y).closest('a')?.textContent.trim(), box);
    await p.mouse.move(5, 5); await p.waitForTimeout(700);
    const left = await st();
    if (!opts.reducedMotion) await p.screenshot({ path: '.playwright-mcp/tile-hover-1440.png', clip: await p.evaluate(() => { const b = document.querySelector('.tile--catalog').getBoundingClientRect(); return { x: b.left, y: b.top, width: b.width, height: b.height }; }) }).catch(() => {});
    // keyboard focus
    await p.focus('.tile--catalog .tile__link'); await p.keyboard.press('Shift+Tab'); await p.keyboard.press('Tab'); await p.waitForTimeout(700);
    const focus = await st();
    await ctx.close();
    return { rest, hover, hitOnImage: hit, left, focus };
  };
  out.push('normal ' + JSON.stringify(await run({})));
  out.push('reduced ' + JSON.stringify(await run({ reducedMotion: 'reduce' })));
  return out.join('\n');
}

