async (page) => {
  const browser = page.context().browser();
  const out = [];
  for (const [w, h, dpr] of [[320, 640, 2], [375, 812, 3], [639, 900, 2], [640, 900, 2], [768, 1024, 2], [1023, 700, 1], [1024, 700, 1], [1920, 1080, 1]]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: dpr });
    const p = await ctx.newPage();
    const errs = []; p.on('pageerror', e => errs.push(String(e)));
    await p.goto('http://127.0.0.1:8765/');
    await p.evaluate(async () => { document.querySelectorAll('img[loading=lazy]').forEach(i => i.loading = 'eager'); await document.fonts.ready; await Promise.all([...document.images].map(i => i.decode().catch(() => {}))); });
    const r = await p.evaluate((dpr) => {
      const R = e => e.getBoundingClientRect();
      const tiles = [...document.querySelectorAll('.tile')].map(t => {
        const img = t.querySelector('.tile__img'), ib = R(img), b = R(t), body = R(t.querySelector('.tile__body'));
        const ar = img.naturalWidth / img.naturalHeight, rendered = Math.max(ib.width, ib.height * ar);
        return `${t.className.match(/tile--(thoro|configurator|catalog|smart)/)[1]} ${Math.round(b.width)}x${Math.round(b.height)} img ${Math.round(ib.width)}x${Math.round(ib.height)} need ${Math.round(rendered * dpr)} got ${img.currentSrc.split('-').pop().replace('.webp', '')} textBelowImg ${body.top >= ib.bottom - 1}`;
      });
      return { overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth, tiles };
    }, dpr);
    if ([375, 768].includes(w)) {
      const sec = await p.evaluate(() => { const b = document.querySelector('.tiles').getBoundingClientRect(); return { y: b.top + scrollY, h: b.height }; });
      await p.screenshot({ path: `.playwright-mcp/tiles-${w}.png`, fullPage: true, clip: { x: 0, y: sec.y, width: w, height: sec.h }, scale: 'css' });
    }
    out.push(`${w}@${dpr}: overflow ${r.overflowX}\n  ` + r.tiles.join('\n  ') + (errs.length ? '\n  errors ' + errs : ''));
    await ctx.close();
  }
