        const lineBox = (el) => { const r = document.createRange(); r.selectNodeContents(el); const rs = [...r.getClientRects()]; const x0 = Math.min(...rs.map(q => q.left)), x1 = Math.max(...rs.map(q => q.right)), y0 = Math.min(...rs.map(q => q.top)), y1 = Math.max(...rs.map(q => q.bottom)); return { x: x0, y: y0, w: x1 - x0, h: y1 - y0 }; };
