const s=require('sharp');(async()=>{
const {data,info}=await s('design/frames/screen.png').removeAlpha().raw().toBuffer({resolveWithObject:true});
const W=info.width,H=info.height;const px=(x,y)=>{const i=(y*W+x)*3;return [data[i],data[i+1],data[i+2]]};
const hex=c=>'#'+c.map(v=>v.toString(16).padStart(2,'0')).join('');
// white-ish text rows (heading & subline): pixels with r,g,b > 200 and low saturation in centre 500-1420
const rows=[];for(let y=0;y<H;y++){let n=0,minx=W,maxx=0;for(let x=500;x<1420;x++){const [r,g,b]=px(x,y);if(r>200&&g>200&&b>200&&Math.abs(r-b)<30){n++;minx=Math.min(minx,x);maxx=Math.max(maxx,x)}}rows.push([n,minx,maxx])}
const runs=[];let st=-1;for(let y=0;y<H;y++){if(rows[y][0]>0&&st<0)st=y;if(rows[y][0]===0&&st>=0){runs.push([st,y-1]);st=-1}}
for(const [a,b] of runs){let mn=W,mx=0;for(let y=a;y<=b;y++){mn=Math.min(mn,rows[y][1]);mx=Math.max(mx,rows[y][2])}console.log('white run y',a,'-',b,'h',b-a+1,'x',mn,'-',mx,'w',mx-mn+1)}
// yellow button: saturated yellow near centre
let by0=H,by1=0,bx0=W,bx1=0;for(let y=380;y<560;y++)for(let x=800;x<1120;x++){const [r,g,b]=px(x,y);if(r>220&&g>170&&b<80){by0=Math.min(by0,y);by1=Math.max(by1,y);bx0=Math.min(bx0,x);bx1=Math.max(bx1,x)}}
console.log('button',bx0,by0,'->',bx1,by1,'size',bx1-bx0+1,'x',by1-by0+1,'colour',hex(px(900,466)));
// subline colour: brightest pixel in subline area
let best=[0];for(let y=512;y<556;y++)for(let x=840;x<1065;x++){const c=px(x,y);const l=c[0]+c[1]+c[2];if(l>best[0])best=[l,c]}console.log('subline brightest',hex(best[1]));
let bh=[0];for(let y=290;y<400;y++)for(let x=630;x<1280;x++){const c=px(x,y);const l=c[0]+c[1]+c[2];if(l>bh[0])bh=[l,c]}console.log('heading brightest',hex(bh[1]));
// background samples on a grid
for(const y of [0,100,200,300,420,500,600,700,780,834]){console.log('y',String(y).padStart(3),[0,200,400,600,800,960,1200,1400,1600,1800,1919].map(x=>hex(px(x,y))).join(' '))}
})()"

