    for (const sz of [16, 17, 18]) r['btn ' + sz] = m('Kup teraz', sz, 700);
    for (const sz of [15, 16]) { r['sub500 ' + sz] = m('Od 119 zł na oficjalnej stronie', sz, 500); r['sub400 ' + sz] = m('Od 119 zł na oficjalnej stronie', sz, 400); }
    return r;
  });
}

