async (page) => {
  return await page.evaluate(async () => {
    await document.fonts.ready;
    const c = document.createElement('canvas').getContext('2d');
    const ink = (text, size, weight, ls = 0) => { c.font = `${weight} ${size}px "Red Hat Display"`; c.letterSpacing = ls + 'px'; const m = c.measureText(text); return +(m.actualBoundingBoxLeft + m.actualBoundingBoxRight).toFixed(1); };
    const r = {};
    for (const sz of [50, 52, 54, 56]) for (const ls of [0, -0.01, -0.02]) r[`h ${sz} ls${ls}`] = [ink('Twoje wnętrze zasługuje na', sz, 700, ls * sz), ink('wyjątkowe światło', sz, 700, ls * sz)];
    for (const sz of [16, 17, 18]) for (const wt of [500, 400]) r[`sub ${sz}/${wt}`] = [ink('Od 119 zł na oficjalnej stronie', sz, wt), ink('producenta SOLLUX', sz, wt)];
    for (const sz of [16, 17, 18, 20]) r[`btn ${sz}`] = ink('Kup teraz', sz, 700);
    return r;
  });
}

