async (page) => {
  const browser = page.context().browser();
  const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
  const p = await ctx.newPage();
  const errs = []; p.on('console', m => m.type() === 'error' && !/404/.test(m.text()) && errs.push(m.text())); p.on('pageerror', e => errs.push(String(e)));
  await p.clock.install({ time: 0 }); await p.clock.pauseAt(1000);
  await p.goto('http://127.0.0.1:8765/');
  await p.addStyleTag({ content: 'html{scrollbar-width:none} .shader__canvas{transition:none!important}' });
  await p.evaluate(() => document.querySelector('.shader').scrollIntoView());
  await p.clock.runFor(100);
  await p.waitForTimeout(500);
  const m = await p.evaluate(() => {
    const sec = document.querySelector('.shader').getBoundingClientRect();
    const ink = (el) => { const r = document.createRange(); r.selectNodeContents(el); return [...r.getClientRects()].map(q => [Math.round(q.left), Math.round(q.top - sec.top), Math.round(q.width), Math.round(q.height)]); };
    const btn = document.querySelector('.shader__cta').getBoundingClientRect();
    const gl = document.createElement('canvas').getContext('webgl');
    const dbg = gl && gl.getExtension('WEBGL_debug_renderer_info');
    return { section: [Math.round(sec.width), Math.round(sec.height)], ready: document.querySelector('.shader').classList.contains('shader--ready'),
      canvas: [document.querySelector('.shader__canvas').width, document.querySelector('.shader__canvas').height],
      titleLines: ink(document.querySelector('.shader__title')), btn: [Math.round(btn.left), Math.round(btn.top - sec.top), Math.round(btn.width), Math.round(btn.height)], note: ink(document.querySelector('.shader__note')),
      renderer: dbg ? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL) : 'n/a' };
  });
  const clip = await p.evaluate(() => { const b = document.querySelector('.shader').getBoundingClientRect(); return { x: 0, y: b.top, width: 1920, height: b.height }; });
  await p.screenshot({ path: '.playwright-mcp/shader-1920.png', clip });
  await ctx.close();
  return JSON.stringify({ m, errs });
}

