// Prints white text runs and the yellow button box of a 1920-wide shader screenshot.
import sharp from 'sharp';
for (const f of process.argv.slice(2)) {
  const { data, info } = await sharp(f).removeAlpha().raw().toBuffer({ resolveWithObject: true });
  const W = info.width, H = info.height, px = (x, y) => { const i = (y * W + x) * 3; return [data[i], data[i + 1], data[i + 2]]; };
  const rows = []; for (let y = 0; y < H; y++) { let n = 0, a = W, b = 0; for (let x = 500; x < 1420; x++) { const [r, g, bl] = px(x, y); if (r > 200 && g > 200 && bl > 200 && Math.abs(r - bl) < 30) { n++; a = Math.min(a, x); b = Math.max(b, x); } } rows.push([n, a, b]); }
  const runs = []; let st = -1; for (let y = 0; y < H; y++) { if (rows[y][0] > 0 && st < 0) st = y; if (rows[y][0] === 0 && st >= 0) { runs.push([st, y - 1]); st = -1; } }
  const out = runs.filter(([a, b]) => b - a > 5).map(([a, b]) => { let mn = W, mx = 0; for (let y = a; y <= b; y++) { mn = Math.min(mn, rows[y][1]); mx = Math.max(mx, rows[y][2]); } return `y ${a}-${b} x ${mn}-${mx} (w ${mx - mn + 1})`; });
  let by0 = H, by1 = 0, bx0 = W, bx1 = 0; for (let y = 380; y < 560; y++) for (let x = 800; x < 1120; x++) { const [r, g, b] = px(x, y); if (r > 220 && g > 170 && b < 80) { by0 = Math.min(by0, y); by1 = Math.max(by1, y); bx0 = Math.min(bx0, x); bx1 = Math.max(bx1, x); } }
  console.log(f.split('/').pop(), '|', out.join(' | '), '| button', bx0, by0, (bx1 - bx0 + 1) + 'x' + (by1 - by0 + 1));
}
EOF
