async (page) => {
  const browser = page.context().browser();
  const log = [];
  // shared: count rAF callbacks scheduled by the page
  const countRaf = () => { window.__raf = 0; const o = window.requestAnimationFrame.bind(window); window.requestAnimationFrame = (cb) => { window.__raf++; return o(cb); }; };

  // 1. seamless loop, compared on the canvas pixels (downscaled 1/8 to average out the 1/255 dither)
  {
    const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
    const p = await ctx.newPage();
    await p.clock.install({ time: 0 }); await p.clock.pauseAt(1000);
    await p.goto('http://127.0.0.1:8765/');
    await p.addStyleTag({ content: '.shader__content{visibility:hidden} .shader__canvas{transition:none!important}' });
    await p.evaluate(() => document.querySelector('.shader').scrollIntoView());
    await p.waitForTimeout(200);
    const grab = async () => {
      const buf = await p.screenshot({ clip: await p.evaluate(() => { const b = document.querySelector('.shader').getBoundingClientRect(); return { x: 0, y: b.top, width: 1920, height: b.height }; }) });
      return await p.evaluate(async (b64) => {
        const img = await new Promise(r => { const i = new Image(); i.onload = () => r(i); i.src = 'data:image/png;base64,' + b64; });
        const c = new OffscreenCanvas(240, 104), g = c.getContext('2d'); g.drawImage(img, 0, 0, 240, 104);
        return Array.from(g.getImageData(0, 0, 240, 104).data);
      }, buf.toString('base64'));
    };
    const diff = (a, b) => { let s = 0, m = 0, n = 0; for (let k = 0; k < a.length; k += 4) for (let c = 0; c < 3; c++) { const d = Math.abs(a[k + c] - b[k + c]); s += d; m = Math.max(m, d); n++; } return { mean: +(s / n).toFixed(2), max: m }; };
    // advance to t0 (first frame after start)
    await p.clock.runFor(50); const f0 = await grab();
    await p.clock.runFor(12450); const fMidA = await grab();
    await p.clock.runFor(100); const fMidB = await grab();
    await p.clock.runFor(12350); const fPre = await grab(); // ~24.95 s
    await p.clock.runFor(100); const fPost = await grab(); // ~25.05 s
