  // cost, real clock
  for (const dpr of [1, 1.5, 2]) {
    const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: dpr });
    const p = await ctx.newPage();
    await p.goto('http://127.0.0.1:8765/');
    await p.evaluate(() => document.querySelector('.shader').scrollIntoView());
    await p.waitForTimeout(400);
    const r = await p.evaluate(() => {
      const c = document.querySelector('.shader__canvas'); const gl = c.getContext('webgl'); const px = new Uint8Array(4);
      const time = () => { gl.drawArrays(gl.TRIANGLES, 0, 3); gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px); const t0 = performance.now(); for (let i = 0; i < 40; i++) { gl.drawArrays(gl.TRIANGLES, 0, 3); gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px); } return +((performance.now() - t0) / 40).toFixed(2); };
      const half = { backing: [c.width, c.height], ms: time() };
      const prog = gl.getParameter(gl.CURRENT_PROGRAM), uRes = gl.getUniformLocation(prog, 'u_res');
      const fw = Math.round(c.clientWidth * Math.min(devicePixelRatio, 1.5)), fh = Math.round(c.clientHeight * Math.min(devicePixelRatio, 1.5));
      c.width = fw; c.height = fh; gl.viewport(0, 0, fw, fh); gl.uniform2f(uRes, fw, fh);
      const full = { backing: [fw, fh], ms: time() };
      return { half, full };
    });
