  await p.waitForTimeout(200);
  const b = (await p.screenshot({ scale: 'css', clip })).toString('base64');
  const cmp = await p.evaluate(async ([a, b]) => {
    const load = s => new Promise(r => { const i = new Image(); i.onload = () => r(i); i.src = 'data:image/png;base64,' + s; });
    const [A, B] = await Promise.all([load(a), load(b)]);
    const g = (img) => { const c = new OffscreenCanvas(img.width, img.height), x = c.getContext('2d'); x.drawImage(img, 0, 0); return x.getImageData(0, 0, img.width, img.height).data; };
    const da = g(A), db = g(B); let s = 0, m = 0, n = 0, over3 = 0; for (let k = 0; k < da.length; k += 4) for (let c = 0; c < 3; c++) { const d = Math.abs(da[k + c] - db[k + c]); s += d; m = Math.max(m, d); n++; if (d > 3) over3++; }
    return { mean: +(s / n).toFixed(2), max: m, pctOver3: +(100 * over3 / n).toFixed(3) };
  }, [a, b]);
