    await p.addInitScript(() => { const o = HTMLCanvasElement.prototype.getContext; HTMLCanvasElement.prototype.getContext = function (t, ...a) { return /webgl/.test(t) ? null : o.call(this, t, ...a); }; });
    await p.goto('http://127.0.0.1:8765/');
    await p.addStyleTag({ content: 'html{scrollbar-width:none}' });
    await p.evaluate(() => document.querySelector('.shader').scrollIntoView());
    await p.waitForTimeout(800);
    const r = await p.evaluate(() => ({ ready: document.querySelector('.shader').classList.contains('shader--ready'), canvasOpacity: getComputedStyle(document.querySelector('.shader__canvas')).opacity }));
    const clip = await p.evaluate(() => { const b = document.querySelector('.shader').getBoundingClientRect(); return { x: 0, y: b.top, width: 1920, height: b.height }; });
    await p.screenshot({ path: '.playwright-mcp/shader-1920-nowebgl.png', clip });
    log.push('no WebGL: ' + JSON.stringify({ ...r, errs }));
    await ctx.close();
  }
  // 2. context lost / restored
  {
    const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
    const p = await ctx.newPage();
    const errs = []; p.on('pageerror', e => errs.push(String(e)));
    await p.addInitScript(() => { window.__draws = 0; const o = WebGLRenderingContext.prototype.drawArrays; WebGLRenderingContext.prototype.drawArrays = function (...a) { window.__draws++; return o.apply(this, a); }; });
    await p.goto('http://127.0.0.1:8765/');
    const r = await p.evaluate(async () => {
      const wait = (ms) => new Promise(r => setTimeout(r, ms));
      const sec = document.querySelector('.shader'); sec.scrollIntoView(); await wait(400);
      const ext = document.querySelector('.shader__canvas').getContext('webgl').getExtension('WEBGL_lose_context');
      ext.loseContext(); await wait(400);
      const lost = { ready: sec.classList.contains('shader--ready') };
      const d0 = window.__draws; await wait(500); lost.drawsWhileLost = window.__draws - d0;
      ext.restoreContext(); await wait(600);
      const d1 = window.__draws; await wait(500);
      return { lost, restored: { ready: sec.classList.contains('shader--ready'), drawsPerHalfSec: window.__draws - d1 } };
    });
    log.push('context lost/restored: ' + JSON.stringify({ ...r, errs }));
    await ctx.close();
  }
  return log.join('\n');
}

