    var renderScale = parseFloat(root.getAttribute('data-render-scale')) || RENDER_SCALE;
    var elapsed = 0;
    var last = null;
    var frame = 0;
    var visible = false;
    var lost = false;
    var resizeTimer = 0;

    function draw() {
      if (lost) return;
      gl.uniform2f(uniforms.res, canvas.width, canvas.height);
      gl.uniform1f(uniforms.phase, (2 * Math.PI * elapsed) / LOOP_MS);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      root.classList.add('shader--ready');
    }

    function resize() {
      var dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR) * renderScale;
      var w = Math.max(1, Math.round(canvas.clientWidth * dpr));
      var h = Math.max(1, Math.round(canvas.clientHeight * dpr));
      if (w !== canvas.width || h !== canvas.height) {
        canvas.width = w;
        canvas.height = h;
        gl.viewport(0, 0, w, h);
      }
      draw();
    }

    function running() {
      return visible && !document.hidden && !reduce.matches && !lost;
    }

    function tick(now) {
      frame = 0;
      // clamp long gaps so the motion never jumps after a stall
      if (last !== null) elapsed = (elapsed + Math.min(now - last, 100)) % LOOP_MS;
      last = now;
      draw();
      update();
    }

    function update() {
      if (running()) {
        if (!frame) frame = requestAnimationFrame(tick);
      } else {
        if (frame) cancelAnimationFrame(frame);
        frame = 0;
        last = null;
      }
    }

    if ('IntersectionObserver' in window) {
      new IntersectionObserver(function (entries) {
        visible = entries[entries.length - 1].isIntersecting;
        update();
      }).observe(root);
    } else {
      visible = true;
    }

    if ('ResizeObserver' in window) {
      new ResizeObserver(function () {
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(resize, RESIZE_DEBOUNCE_MS);
      }).observe(canvas);
    }

    document.addEventListener('visibilitychange', update);
    reduce.addEventListener('change', update);

    canvas.addEventListener('webglcontextlost', function (event) {
      event.preventDefault();
      lost = true;
      root.classList.remove('shader--ready'); // back to the CSS gradient
      update();
    });
    canvas.addEventListener('webglcontextrestored', function () {
      uniforms = setup(gl);
      if (!uniforms) return;
      lost = false;
      resize();
      update();
    });

    resize();
    update();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
