async (page) => {
  const browser = page.context().browser();
  const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
  const p = await ctx.newPage();
  const errs = []; p.on('console', m => m.type() === 'error' && !/404/.test(m.text()) && errs.push(m.text())); p.on('pageerror', e => errs.push(String(e)));
  await p.goto('http://127.0.0.1:8765/');
  await p.addStyleTag({ content: 'html{scrollbar-width:none}' });
  await p.evaluate(async () => { document.querySelectorAll('img[loading=lazy]').forEach(i => i.loading = 'eager'); await document.fonts.ready; await Promise.all([...document.images].map(i => i.decode().catch(() => {}))); });
  const m = await p.evaluate(() => {
    const f = document.querySelector('.footer'), fb = f.getBoundingClientRect(), top = fb.top + scrollY;
    const r = (el) => { const b = el.getBoundingClientRect(); return [Math.round(b.left), Math.round(b.top + scrollY - top), Math.round(b.width), Math.round(b.height)]; };
    const ink = (el) => { const rg = document.createRange(); rg.selectNodeContents(el); const b = rg.getBoundingClientRect(); return [Math.round(b.left), Math.round(b.top + scrollY - top), Math.round(b.width), Math.round(b.height)]; };
    return { footer: [Math.round(fb.width), Math.round(fb.height)], logo: r(document.querySelector('.footer__logo svg')), social: [...document.querySelectorAll('.footer__social-link svg')].map(r),
      headings: [...document.querySelectorAll('.footer__nav .footer__heading')].map(ink), firstLinks: [...document.querySelectorAll('.footer__links')].map(u => ink(u.querySelector('a'))), lastLink4: ink([...document.querySelectorAll('.footer__links')][3].lastElementChild.querySelector('a')),
      bottomTop: r(document.querySelector('.footer__bottom')), groups: [...document.querySelectorAll('.footer__group')].map(r), groupHeads: [...document.querySelectorAll('.footer__group .footer__heading')].map(ink),
      pay: [...document.querySelectorAll('.footer__payment img')].slice(0, 6).map(r), awards: [...document.querySelectorAll('.footer__awards img')].map(r), flags: [...document.querySelectorAll('.footer__flag img')].slice(0, 2).map(r),
      vat: ink(document.querySelector('.footer__vat p')), rule: r(document.querySelector('.footer__rule')), badges: [...document.querySelectorAll('.footer__badges img')].map(r), contact: [...document.querySelectorAll('.footer__contact li')].map(ink) };
  });
  const clip = await p.evaluate(() => { const b = document.querySelector('.footer').getBoundingClientRect(); return { x: 0, y: b.top + scrollY, width: 1920, height: b.height }; });
  await p.screenshot({ path: '.playwright-mcp/footer-1920.png', fullPage: true, clip });
  await ctx.close();
  return JSON.stringify({ m, errs });
}

