### Result
"{\"y\":3339.010498046875,\"h\":712.4896240234375,\"bottomTop\":382.333251953125}"
### Ran Playwright code
```js
await (async (page) => {
  const browser = page.context().browser();
  const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
  const p = await ctx.newPage();
  await p.goto('http://127.0.0.1:8765/');
  await p.addStyleTag({ content: 'html{scrollbar-width:none}' });
  await p.evaluate(async () => { document.querySelectorAll('img[loading=lazy]').forEach(i => i.loading = 'eager'); await document.fonts.ready; await Promise.all([...document.images].map(i => i.decode().catch(() => {}))); });
  const h = await p.evaluate(() => { const b = document.querySelector('.footer').getBoundingClientRect(); return { y: b.top + scrollY, h: b.height, bottomTop: document.querySelector('.footer__bottom').getBoundingClientRect().top - b.top }; });
  await p.screenshot({ path: '.playwright-mcp/footer-1920.png', fullPage: true, clip: { x: 0, y: h.y, width: 1920, height: Math.round(h.h) } });
  await ctx.close();
  return JSON.stringify(h);
})(page);
```

