const s=require('sharp');(async()=>{
const a=await s('.playwright-mcp/footer-1920.png').removeAlpha().raw().toBuffer({resolveWithObject:true});
const b=await s('design/frames/footer.png').removeAlpha().raw().toBuffer({resolveWithObject:true});
console.log('mine',a.info.width,a.info.height,'frame',b.info.width,b.info.height);
const W=1920,H=Math.min(a.info.height,b.info.height);
// row profile: first/last rows that contain dark ink per band, and horizontal rule rows
const rows=(img,h)=>{const out=[];for(let y=0;y<h;y++){let n=0;for(let x=150;x<1770;x++){const i=(y*W+x)*3;if(img.data[i]<120)n++}out.push(n)}return out};
const ra=rows(a,a.info.height),rb=rows(b,b.info.height);
const runs=(r)=>{const o=[];let st=-1;for(let y=0;y<r.length;y++){if(r[y]>0&&st<0)st=y;if(r[y]===0&&st>=0){o.push(st+'-'+(y-1));st=-1}}return o};
console.log('ink runs mine :',runs(ra).join(' '));console.log('ink runs frame:',runs(rb).join(' '));
// light-grey rule rows (#e7e7e7 lines): count of pixels 225-235 across the width
const lines=(img,h)=>{const o=[];for(let y=0;y<h;y++){let n=0;for(let x=150;x<1770;x++){const i=(y*W+x)*3;if(img.data[i]>=220&&img.data[i]<=240&&Math.abs(img.data[i]-img.data[i+2])<6)n++}if(n>400)o.push(y+':'+n)}return o};
console.log('rules mine :',lines(a,a.info.height).join(' '));console.log('rules frame:',lines(b,b.info.height).join(' '));
let t=0,n=0;for(let y=0;y<H;y++)for(let x=0;x<W;x++){const i=(y*W+x)*3;t+=Math.abs(a.data[i]-b.data[i])+Math.abs(a.data[i+1]-b.data[i+1])+Math.abs(a.data[i+2]-b.data[i+2]);n+=3}console.log('mean diff',(t/n).toFixed(2));
})()"

