async (page) => {
  const browser = page.context().browser();
  const out = [];
  for (const [w, h, dpr] of [[320, 640, 2], [375, 812, 3], [640, 900, 2], [768, 1024, 2], [1023, 700, 1], [1024, 700, 1], [1279, 633, 1], [1280, 633, 1.5], [1440, 789, 1], [1920, 1080, 1], [2560, 1080, 1]]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: dpr });
    const p = await ctx.newPage();
    const errs = []; p.on('console', m => m.type() === 'error' && !/404/.test(m.text()) && errs.push(m.text())); p.on('pageerror', e => errs.push(String(e)));
    await p.goto('http://127.0.0.1:8765/');
    await p.evaluate(async () => { document.querySelectorAll('img[loading=lazy]').forEach(i => i.loading = 'eager'); await document.fonts.ready; await Promise.all([...document.images].map(i => i.decode().catch(() => {}))); });
    const r = await p.evaluate(() => {
      const f = document.querySelector('.footer'), fb = f.getBoundingClientRect(), R = e => e.getBoundingClientRect();
      const cut = [...f.querySelectorAll('a, img, p, li, h2')].filter(e => { const b = R(e); return b.width > 0 && (b.right > innerWidth + 0.5 || b.left < -0.5); }).map(e => e.textContent.trim().slice(0, 18) || e.getAttribute('alt'));
      const textOverflow = [...f.querySelectorAll('.footer__link, .footer__heading, .footer__vat p, .footer__contact li')].filter(e => e.scrollWidth > e.clientWidth + 1).map(e => e.textContent.trim().slice(0, 18));
      const navCols = new Set([...f.querySelectorAll('.footer__column')].map(c => Math.round(R(c).left))).size;
      const navRows = new Set([...f.querySelectorAll('.footer__column')].map(c => Math.round(R(c).top))).size;
      const groupsRow = new Set([...f.querySelectorAll('.footer__group')].map(g => Math.round(R(g).top))).size === 1;
      const brandBesideNav = Math.round(R(f.querySelector('.footer__brand')).top) === Math.round(R(f.querySelector('.footer__nav')).top);
      const minTap = Math.min(...[...f.querySelectorAll('a')].map(a => R(a).height));
      return { overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth, footerH: Math.round(fb.height), navCols, navRows, brandBesideNav, groupsInOneRow: groupsRow, rule: getComputedStyle(f.querySelector('.footer__rule')).display, cut, textOverflow, minLinkHeight: Math.round(minTap) };
    });
    if ([375, 768, 1280].includes(w)) {
      const clip = await p.evaluate(() => { const b = document.querySelector('.footer').getBoundingClientRect(); return { x: 0, y: b.top + scrollY, width: innerWidth, height: b.height }; });
      await p.screenshot({ path: `.playwright-mcp/footer-${w}.png`, fullPage: true, clip, scale: 'css' });
    }
    out.push(`${w}: ${JSON.stringify({ ...r, errs })}`);
    await ctx.close();
  }
  return out.join('\n');
}

