  const lines=[];for(let k=1;k<10;k++){lines.push('<line x1=\"'+(w*k/10)+'\" y1=\"0\" x2=\"'+(w*k/10)+'\" y2=\"'+h+'\" stroke=\"cyan\" stroke-width=\"1\" opacity=\"0.6\"/>');lines.push('<line x1=\"0\" y1=\"'+(h*k/10)+'\" x2=\"'+w+'\" y2=\"'+(h*k/10)+'\" stroke=\"cyan\" stroke-width=\"1\" opacity=\"0.6\"/>');lines.push('<text x=\"'+(w*k/10+2)+'\" y=\"12\" font-size=\"11\" fill=\"cyan\">'+k*10+'</text><text x=\"2\" y=\"'+(h*k/10-2)+'\" font-size=\"11\" fill=\"cyan\">'+k*10+'</text>')}
