// Prototype for the lamp-glow proposal (not project code). Injected into the
// page by Playwright; renders the "on" state of one option for a still.
// Geometry in % of the 1920x1080 stage, read from the lamp PNGs.
window.__glowProto = function (option, opts) {
  opts = opts || {};
  const P = (px, total) => (px / total) * 100 + '%';
  const lamps = [
    { d: [983, 362], disc: [210, 120, -22], cone: [63, 520, 300], pool: [1225, 835, 300, 70] },
    { d: [1156, 679], disc: [85, 125, 25], cone: [143, 230, 170], pool: [975, 815, 230, 55] },
    { d: [698, 684], disc: [250, 130, -20], cone: [60, 210, 230], pool: [800, 862, 260, 60] },
  ];
  const presets = {
    // A: natural - diffuser glow, soft cone, faint pool
