    await p.evaluate(([o, x]) => window.__glowProto(o, x), [opt, opts]);
    await p.waitForTimeout(800);
    await p.screenshot({ path: file });
    await ctx.close();
  };
  for (const opt of ['A', 'B', 'C']) await shot(opt, {}, `.playwright-mcp/glow-${opt}.png`);
  // discoverability state: nothing on, hint shown, hover glow on lamp 2
  await shot('A', { on: [], hint: true, hoverOnly: 1, noEgg: true }, '.playwright-mcp/glow-hint.png');
  // option A on slide 2, one lamp on
  await shot('A', { on: [2], slide: 2, noEgg: true }, '.playwright-mcp/glow-A-slide2.png');
  return 'ok';
}

