async (page) => {
  const browser = page.context().browser();
  const log = [];
  const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
  const p = await ctx.newPage();
  const errs = []; p.on('console', m => m.type() === 'error' && !/404/.test(m.text()) && errs.push(m.text())); p.on('pageerror', e => errs.push(String(e)));
  await p.clock.install({ time: 0 }); await p.clock.pauseAt(1000);
  await p.goto('http://127.0.0.1:8765/');
  await p.addStyleTag({ content: 'html{scrollbar-width:none}' });
  await p.waitForTimeout(300);
  // 1. no lamps on == hero without the new layers (hint hidden for the comparison)
  await p.evaluate(() => { document.querySelector('[data-lamp-hint]').style.visibility = 'hidden'; });
  const a = (await p.screenshot()).toString('base64');
  await p.evaluate(() => { document.querySelectorAll('.hero__dim, .hero__stage--light').forEach(e => e.remove()); });
  const b = (await p.screenshot()).toString('base64');
  const same = await p.evaluate(async ([a, b]) => {
    const load = s => new Promise(r => { const i = new Image(); i.onload = () => r(i); i.src = 'data:image/png;base64,' + s; });
    const [A, B] = await Promise.all([load(a), load(b)]);
    const g = (img) => { const c = new OffscreenCanvas(img.width, img.height), x = c.getContext('2d'); x.drawImage(img, 0, 0); return x.getImageData(0, 0, img.width, img.height).data; };
    const da = g(A), db = g(B); let diff = 0; for (let k = 0; k < da.length; k++) if (da[k] !== db[k]) diff++; return diff;
  }, [a, b]);
  log.push('no lamps on vs without light layers: differing bytes = ' + same);
  await ctx.close();

  // 2. behaviour
  const ctx2 = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
  const q = await ctx2.newPage();
  q.on('pageerror', e => errs.push(String(e)));
  await q.goto('http://127.0.0.1:8765/');
  const st = () => q.evaluate(() => {
    const hero = document.querySelector('.hero');
    return { lit: [1, 2, 3].filter(n => hero.classList.contains('hero--lit-' + n)).join(''), dim: getComputedStyle(document.querySelector('.hero__dim')).opacity,
      pressed: [...document.querySelectorAll('[data-lamp]')].map(l => l.getAttribute('aria-pressed') === 'true' ? 1 : 0).join(''),
      on: [...document.querySelectorAll('[data-light]')].map(l => l.classList.contains('light--on') ? 1 : 0).join(''),
      egg: getComputedStyle(document.querySelector('.hero__glow'), '::after').opacity, hintHidden: document.querySelector('[data-lamp-hint]').hidden,
      flicker: document.getAnimations().filter(a => a.animationName === 'lamp-flicker').length };
  });
  log.push('start: ' + JSON.stringify(await st()));
  await q.click('.lamp--2'); await q.waitForTimeout(100);
  log.push('lamp 2 on (100 ms): ' + JSON.stringify(await st()));
  await q.waitForTimeout(800);
  log.push('lamp 2 on (900 ms): ' + JSON.stringify(await st()) + ' storage=' + await q.evaluate(() => localStorage.getItem('sollux:lamp-hint-seen')));
  await q.click('.lamp--1'); await q.waitForTimeout(900);
  log.push('lamps 1+2: ' + JSON.stringify(await st()));
  // keyboard on lamp 3
  await q.focus('.lamp--3'); await q.keyboard.press('Enter'); await q.waitForTimeout(1000);
  log.push('lamp 3 via Enter (all on): ' + JSON.stringify(await st()));
  await q.keyboard.press('Space'); await q.waitForTimeout(900);
  log.push('lamp 3 off via Space: ' + JSON.stringify(await st()));
  await q.click('.lamp--1'); await q.click('.lamp--2'); await q.waitForTimeout(900);
  log.push('all off: ' + JSON.stringify(await st()));
  log.push('heading accessible name: ' + JSON.stringify(await q.evaluate(async () => { return document.querySelector('.hero__title').innerText; })) );
  const snap = await q.accessibility?.snapshot?.({ root: await q.$('.hero__title') }).catch(() => null);
  log.push('a11y snapshot of h1: ' + JSON.stringify(snap));
  await q.reload(); await q.waitForTimeout(300);
  log.push('after reload hint hidden: ' + await q.evaluate(() => document.querySelector('[data-lamp-hint]').hidden));
  await ctx2.close();
  log.push('errors ' + JSON.stringify(errs));
  return log.join('\n');
}

