await (async (page) => {
  const browser = page.context().browser();
  const run = async (remove, act) => {
    const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
    const p = await ctx.newPage();
    await p.clock.install({ time: 0 }); await p.clock.pauseAt(1000);
    await p.goto('http://127.0.0.1:8765/');
    await p.addStyleTag({ content: 'html{scrollbar-width:none} [data-lamp-hint]{visibility:hidden!important}' });
    if (remove) await p.evaluate((sel) => document.querySelectorAll(sel).forEach(e => e.remove()), remove);
    if (act) await act(p);
    await p.mouse.move(5, 1000);
    await p.waitForTimeout(900);
    const buf = (await p.screenshot()).toString('base64');
    await ctx.close();
    return buf;
  };
  const cmp = async (a, b) => page.evaluate(async ([a, b]) => {
    const load = s => new Promise(r => { const i = new Image(); i.onload = () => r(i); i.src = 'data:image/png;base64,' + s; });
    const [A, B] = await Promise.all([load(a), load(b)]);
    const g = (img) => { const c = new OffscreenCanvas(img.width, img.height), x = c.getContext('2d'); x.drawImage(img, 0, 0); return x.getImageData(0, 0, img.width, img.height).data; };
    const da = g(A), db = g(B); let n = 0; for (let k = 0; k < da.length; k += 4) if (da[k] !== db[k] || da[k + 1] !== db[k + 1] || da[k + 2] !== db[k + 2]) n++; return n;
  }, [a, b]);
  const base = await run('.hero__dim, .hero__stage--light');
  const fresh = await run(null);
  // a lamp switched on and off again (after the off-fade the layer must be hidden again)
  const onOff = await run(null, async (p) => { await p.evaluate(() => { document.querySelector('.lamp--2').click(); }); await p.waitForTimeout(700); await p.evaluate(() => { document.querySelector('.lamp--2').click(); }); });
  return JSON.stringify({ freshLoad_differingPixels: await cmp(base, fresh), afterOnAndOff_differingPixels: await cmp(base, onOff) });
})(page);
