async (page) => {
  const browser = page.context().browser();
  const out = [];
  const shot = async (name, { w = 1920, h = 1080, dpr = 1, on = [], slide = 1, rm = false, hover = null } = {}) => {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: dpr, reducedMotion: rm ? 'reduce' : 'no-preference' });
    const p = await ctx.newPage();
    const errs = []; p.on('pageerror', e => errs.push(String(e)));
    await p.clock.install({ time: 0 }); await p.clock.pauseAt(1000);
    await p.goto('http://127.0.0.1:8765/');
    await p.addStyleTag({ content: 'html{scrollbar-width:none}' });
    if (slide === 2) await p.click('[data-slider-next]').catch(() => p.evaluate(() => document.querySelectorAll('[data-slider-dot]')[1].click()));
    for (const n of on) await p.evaluate((n) => document.querySelector('.lamp--' + n).click(), n);
    if (hover) { const b = await p.evaluate((n) => { const r = document.querySelector('.lamp--' + n + ' img').getBoundingClientRect(); return { x: r.left + r.width * 0.5, y: r.top + r.height * 0.5 }; }, hover); await p.mouse.move(b.x, b.y); } else await p.mouse.move(2, h - 2);
    await p.waitForTimeout(1800);
    await p.screenshot({ path: `.playwright-mcp/lamps-${name}.png`, scale: 'css' });
    const r = await p.evaluate(() => {
      const hint = document.querySelector('[data-lamp-hint]'), hb = hint.getBoundingClientRect();
      return { overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth, hint: hint.hidden ? 'hidden' : `${Math.round(hb.left)},${Math.round(hb.top)} ${Math.round(hb.width)}x${Math.round(hb.height)} inView=${hb.left >= 0 && hb.right <= innerWidth && hb.bottom <= innerHeight}`, dim: getComputedStyle(document.querySelector('.hero__dim')).opacity };
    });
    out.push(`${name}: ${JSON.stringify({ ...r, errs })}`);
    await ctx.close();
  };
  await shot('1920-one', { on: [2] });
  await shot('1920-all', { on: [1, 2, 3] });
  await shot('1920-slide2-all', { on: [1, 2, 3], slide: 2 });
  await shot('1920-hover', { hover: 2 });
  await shot('1280-all', { w: 1280, h: 633, dpr: 1.5, on: [1, 2, 3] });
