async (page) => {
  const browser = page.context().browser();
  const log = [];
  for (const rm of ['no-preference', 'reduce']) {
    const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, reducedMotion: rm });
    const p = await ctx.newPage();
    await p.goto('http://127.0.0.1:8765/');
    await p.waitForTimeout(1500);
    const idleBefore = await p.evaluate(() => document.getAnimations().filter(a => a.playState === 'running').map(a => a.animationName || a.transitionProperty || 'anim'));
    await p.evaluate(() => document.querySelector('.lamp--1').click());
    // sample the glow opacity every 30 ms for 700 ms
    const curve = await p.evaluate(async () => { const g = document.querySelector('.light--1 .light__glow'); const out = []; for (let i = 0; i < 24; i++) { out.push(+(+getComputedStyle(g).opacity).toFixed(2)); await new Promise(r => setTimeout(r, 30)); } return out; });
    await p.waitForTimeout(800);
    const idleAfter = await p.evaluate(() => document.getAnimations().filter(a => a.playState === 'running').map(a => a.animationName || a.transitionProperty || 'anim'));
    const transformAnims = await p.evaluate(() => document.getAnimations().length);
    log.push(`${rm}: running before click ${JSON.stringify(idleBefore)} | switch-on opacity curve ${JSON.stringify(curve)} | running when settled ${JSON.stringify(idleAfter)}`);
    await ctx.close();
  }
  return log.join('\n');
}

