// Hero slider (PLAN.md §3.4, comments spec 04).
// - Autoplay every --slide-interval (3 s); the crossfade and zoom are CSS
//   transitions on the class change (css/hero.css).
// - The progress bar is driven from the same clock, so bar and slide change
//   never drift apart. Timing uses requestAnimationFrame + performance.now,
//   which Playwright's page.clock controls.
// - Pauses while a control is hovered, while keyboard focus is inside the
//   hero, while the tab is hidden and while the hero is off-screen.
// - Pause/play toggle next to the progress bar (WCAG 2.2.2).
// - Reduced motion: no autoplay (manual changes still crossfade).
// - Lamp overlay images are shown on slides marked data-slide-lamps.
(function () {
  'use strict';

  var SWIPE_MIN = 50; // px

  function parseTime(value) {
    var text = String(value).trim();
    var n = parseFloat(text);
    if (isNaN(n)) return 0;
    return /ms$/.test(text) ? n : n * 1000;
  }

  function init() {
    var root = document.querySelector('[data-slider]');
    if (!root) return;

    var slides = root.querySelectorAll('[data-slide]');
    var dots = root.querySelectorAll('[data-slider-dot]');
    var lamps = root.querySelector('[data-lamps]');
    var controls = root.querySelectorAll(
      '[data-slider-prev], [data-slider-next], [data-slider-progress]',
    );
    if (slides.length < 2) return;

    var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
    var interval = parseTime(getComputedStyle(root).getPropertyValue('--slide-interval')) || 3000;

    var index = 0;
    var elapsed = 0;
    var last = null;
    var frame = 0;
    var pauseButton = root.querySelector('[data-slider-pause]');
    var paused = { hover: false, focus: false, hidden: document.hidden, offscreen: false };
    // Explicit choice from the pause/play toggle: null (not used), 'paused' or
    // 'playing'. Once used it wins over the automatic hover/focus pauses, so
    // pressing "play" with the keyboard (focus still inside) really plays.
    var userChoice = null;

    function autoplay() {
      if (reduce.matches || paused.hidden || paused.offscreen) return false;
      if (userChoice) return userChoice === 'playing';
      return !paused.hover && !paused.focus;
    }

    function renderProgress() {
      Array.prototype.forEach.call(dots, function (dot, i) {
        var fill = dot.firstElementChild;
        if (!fill) return;
        // Inline transform only while autoplay is possible; otherwise the CSS
        // default applies (active bar full, others empty).
        fill.style.transform =
          i === index && !reduce.matches ? 'scaleX(' + Math.min(elapsed / interval, 1) + ')' : '';
      });
    }

    function show(next) {
      index = (next + slides.length) % slides.length;
      elapsed = 0;
      Array.prototype.forEach.call(slides, function (slide, i) {
        var active = i === index;
        slide.classList.toggle('hero__slide--active', active);
        if (active) slide.removeAttribute('aria-hidden');
        else slide.setAttribute('aria-hidden', 'true');
      });
      Array.prototype.forEach.call(dots, function (dot, i) {
        var active = i === index;
        dot.classList.toggle('hero__dot--active', active);
        if (active) dot.setAttribute('aria-current', 'true');
        else dot.removeAttribute('aria-current');
      });
      if (lamps) {
        lamps.classList.toggle(
          'hero__stage--lamps-visible',
          slides[index].hasAttribute('data-slide-lamps'),
        );
      }
      renderProgress();
    }

    function tick(now) {
      frame = 0;
      // Clamp long gaps (throttled frames) so the bar never skips ahead.
      if (last !== null) elapsed += Math.min(now - last, 100);
      last = now;
      if (elapsed >= interval) show(index + 1);
      else renderProgress();
      update();
    }

    function update() {
      if (autoplay()) {
        if (!frame) frame = requestAnimationFrame(tick);
      } else {
        if (frame) cancelAnimationFrame(frame);
        frame = 0;
        last = null;
        renderProgress();
      }
    }

    function go(step) {
      show(index + step);
      update();
    }

    root.querySelector('[data-slider-prev]').addEventListener('click', function () {
      go(-1);
    });
    root.querySelector('[data-slider-next]').addEventListener('click', function () {
      go(1);
    });
    Array.prototype.forEach.call(dots, function (dot, i) {
      dot.addEventListener('click', function () {
        if (i !== index) go(i - index);
      });
    });

    // Keyboard: arrow keys while focus is inside the hero.
    root.addEventListener('keydown', function (event) {
      if (event.key === 'ArrowLeft') go(-1);
      else if (event.key === 'ArrowRight') go(1);
    });

    // Pause on hover over the controls (mouse only; touch has no hover).
    Array.prototype.forEach.call(controls, function (el) {
      el.addEventListener('pointerenter', function (event) {
        if (event.pointerType !== 'mouse') return;
        paused.hover = true;
        update();
      });
      el.addEventListener('pointerleave', function (event) {
        if (event.pointerType !== 'mouse') return;
        paused.hover = false;
        update();
      });
    });

    // Pause while keyboard focus is inside (mouse clicks don't match :focus-visible).
    root.addEventListener('focusin', function (event) {
      paused.focus = event.target.matches(':focus-visible');
      update();
    });
    root.addEventListener('focusout', function (event) {
      if (!root.contains(event.relatedTarget)) {
        paused.focus = false;
        update();
      }
    });

    document.addEventListener('visibilitychange', function () {
      paused.hidden = document.hidden;
      update();
    });

    if ('IntersectionObserver' in window) {
      new IntersectionObserver(function (entries) {
        paused.offscreen = !entries[entries.length - 1].isIntersecting;
        update();
      }).observe(root);
    }

    // Pause/play toggle (WCAG 2.2.2). Hidden under reduced motion, where
    // there is no autoplay to pause.
    function syncPauseButton() {
      if (!pauseButton) return;
      pauseButton.hidden = reduce.matches;
      pauseButton.setAttribute('aria-pressed', String(userChoice === 'paused'));
    }

    if (pauseButton) {
      pauseButton.addEventListener('click', function () {
        userChoice = userChoice === 'paused' ? 'playing' : 'paused';
        syncPauseButton();
        update();
      });
    }

    reduce.addEventListener('change', function () {
      syncPauseButton();
      update();
    });
    syncPauseButton();

    // Touch swipe (the arrows are hidden below 1024 px).
    var start = null;
    root.addEventListener('pointerdown', function (event) {
      start = event.pointerType === 'touch' ? { x: event.clientX, y: event.clientY } : null;
    });
    root.addEventListener('pointerup', function (event) {
      if (!start) return;
      var dx = event.clientX - start.x;
      var dy = event.clientY - start.y;
      start = null;
      if (Math.abs(dx) >= SWIPE_MIN && Math.abs(dx) > Math.abs(dy)) go(dx < 0 ? 1 : -1);
    });
    root.addEventListener('pointercancel', function () {
      start = null;
    });

    show(0);
    update();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
/* Hero (Figma 1:506, PLAN.md §0.3 / §3.3). Static: no slide animation yet.

   Two layouts share one rule: everything that must stay aligned with the photo
   (slide images and lamps) lives in a `.hero__stage` box with the photo's
   1920:1080 ratio, positioned identically.

   - Cover mode (landscape): the stage covers the hero like object-fit: cover.
   - Contained mode (portrait, max-aspect-ratio 5/4): covering would crop the
     lamps, so the stage is sized so the lamp group fits the viewport width and
     sits at the bottom. Above it, the slide's own sky colour (sampled from the
     photo's top edge) continues the image; the stage's top edge fades into it. */
.hero {
  --hero-h: clamp(560px, 100svh, 1080px);

  /* only ever used for `width`: the 100% must resolve against the hero's width */
  --stage-w: max(100%, var(--hero-h) * 16 / 9);
  --arrow-size: 48px;
  --arrow-inset: 72px;

  /* while the arrows show, text starts this far from the hero edge
     (inset + arrow + 24 px gap); at 1920 the 1600 column is wider anyway */
  --arrow-clear: calc(var(--arrow-inset) + var(--arrow-size) + 24px);

  /* centre of the lamp group in the stage (lamp-positions.json): x 21.77-80.52 %, y 7.87-76.58 % */
  --lamps-origin: 51.15% 42.2%;

  position: relative;
  display: grid;
  height: var(--hero-h);
  overflow: hidden;
  color: var(--c-white);
  background: var(--c-black);

  /* horizontal swipes go to the slider (js/hero-slider.js), vertical ones scroll */
  touch-action: pan-y;
}

.hero__slides {
  position: absolute;
  inset: 0;
}

/* Crossfade (comments spec 04): 600 ms ease-in-out, both ways. */
.hero__slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity var(--dur-fade) var(--ease);
}

.hero__slide--active {
  opacity: 1;
}

/* Top-edge colour of each photo; scrim keeps white text >= 4.5:1 on mobile */
.hero__slide--rock {
  --hero-sky: #9c6744;
  --hero-scrim: 0%;
}

.hero__slide--interior {
  --hero-sky: #c5afa3;
  --hero-scrim: 45%;
}

/* Height comes from aspect-ratio, never from a calc on --stage-w: inside
   `height`, the 100% in --stage-w would resolve against the hero's height and
   squash the photo on viewports wider than 16:9 (e.g. 1280 x 633). */
.hero__stage {
  position: absolute;
  top: 50%;
  left: 50%;
  width: var(--stage-w);
  aspect-ratio: 1920 / 1080;
  transform: translate(-50%, -50%);
}

/* Incoming image zooms 1.05 -> 1 over 800 ms ease-out. An inactive image
   waits at 1.05, but only snaps there after its own fade-out has finished,
   so the outgoing slide never jumps. Origin: the lamp group's centre, which
   keeps the baked lamps closest to the overlays while the zoom runs. */
.hero__img {
  width: 100%;
  height: 100%;
  transform-origin: var(--lamps-origin);
  scale: var(--scale-slide-in);
  transition: scale 0s linear var(--dur-fade);
}

.hero__slide--active .hero__img {
  scale: 1;
  transition: scale var(--dur-zoom) var(--ease-out);
}

/* Lamps */
.hero__stage--lamps {
  z-index: 1;
}

.lamp {
  position: absolute;
  top: var(--y);
  left: var(--x);
  width: var(--w);
}

/* Slide 1 has the lamps baked into the photo, so the overlay images stay
   hidden there (no reliance on pixel-perfect alignment); only the click glow
   shows. They fade in together with slide 2's crossfade. Going back, they
   hold until slide 1's zoom has settled (--dur-zoom; 0 under reduced motion)
   and then fade out over the baked lamps, which by then are in place. The
   buttons stay in place and clickable on both slides. */
.lamp__img {
  width: 100%;
  opacity: 0;
  transition: opacity var(--dur-fade) var(--ease) var(--dur-zoom);
}

.hero__stage--lamps-visible .lamp__img {
  opacity: 1;
  transition-delay: 0s;
}

/* Text block: grid item on top of the absolute layers */
.hero__content {
  z-index: 2;
  grid-area: 1 / 1;
  align-self: center;
  width: min(100% - 2 * var(--gutter), var(--container));
  margin-inline: auto;
  padding-block: 64px;
  pointer-events: none;
}

.hero__inner {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.hero__inner > * {
  pointer-events: auto;
}

.hero__eyebrow {
  font-size: var(--fs-16);
  font-weight: var(--fw-medium);
  line-height: 1.2;
}

.hero__title {
  margin-top: 16px;
  font-size: var(--fs-hero);
  font-weight: var(--fw-bold);
  line-height: 1;
}

.hero__cta {
  margin-top: 32px;
}

/* Trustmate badge: bottom right of the hero on desktop (absolute against
   .hero, since .hero__content is not positioned), in the text flow on mobile. */
.hero__badge {
  display: inline-flex;
  gap: 12px;
  align-items: center;
  margin-top: 24px;
  padding: 12px 24px;
  font-size: var(--fs-13);
  font-weight: var(--fw-medium);
  line-height: 1.1;
  white-space: nowrap;
  background: var(--c-badge-bg);
  border-radius: var(--radius-pill);
}

.hero__rating {
  display: inline-flex;
  gap: 2px;
  align-items: center;
  font-size: var(--fs-21);
  font-weight: var(--fw-bold);
}

/* Arrows: hidden below 1024 (PLAN.md §5, proposed) */
.hero__arrow {
  position: absolute;
  top: 50%;
  z-index: 3;
  display: none;
  place-items: center;
  width: var(--arrow-size);
  height: var(--arrow-size);
  color: var(--c-line);
  background: var(--c-control-bg);
  border-radius: var(--radius-pill);
  transform: translateY(-50%);
  isolation: isolate;
}

/* Hover (not in the design; simplest consistent option): a second layer of
   the same translucent black fades in, as with the buttons' overlay. */
.hero__arrow::before {
  position: absolute;
  inset: 0;
  z-index: -1;
  content: '';
  background: var(--c-control-bg);
  border-radius: inherit;
  opacity: 0;
  transition: opacity var(--dur-button) var(--ease);
}

@media (hover: hover) {
  .hero__arrow:hover::before {
    opacity: 1;
  }
}

.hero__arrow--prev {
  left: var(--arrow-inset);
}

.hero__arrow--next {
  right: var(--arrow-inset);
}

/* Progress: 2 x 64 x 2 px bars; the buttons are 44 px tall tap targets.
   While autoplaying, js/hero-slider.js sets the active fill's scaleX every
   frame (linear over --slide-interval). Without autoplay (reduced motion, no
   JS) the active bar is simply full. */
.hero__progress {
  position: absolute;
  bottom: 11px; /* 32 px to the bar = 11 + (44 - 2) / 2 */
  left: 50%;
  z-index: 3;
  display: flex;
  gap: 4px;
  transform: translateX(-50%);
}

.hero__dot {
  position: relative;
  width: 64px;
  height: 44px;
}

.hero__dot::before,
.hero__dot-fill {
  position: absolute;
  inset: 21px 0;
}

.hero__dot::before {
  content: '';
  background: var(--c-track);
}

.hero__dot-fill {
  background: var(--c-yellow);
  transform: scaleX(0);
  transform-origin: left;
}

.hero__dot--active .hero__dot-fill {
  transform: scaleX(1);
}

/* Pause/play toggle (WCAG 2.2.2): styled like the bar, white icon, no
   background. Sits just right of the segments, outside the centred group, so
   the segments stay centred. 44 x 44 tap target. aria-pressed="true" means
   paused, so the icon switches to "play". */
.hero__pause {
  position: absolute;
  top: 0;
  left: calc(100% + 4px);
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  color: var(--c-white);
}

.hero__pause[hidden] {
  display: none;
}

.hero__pause[aria-pressed='true'] .hero__pause-icon--pause,
.hero__pause[aria-pressed='false'] .hero__pause-icon--play {
  display: none;
}

@media (width >= 1024px) {
  .hero__arrow {
    display: grid;
  }

  .hero__content {
    width: min(100% - 2 * var(--arrow-clear), var(--container));
  }

  .hero__badge {
    position: absolute;
    right: var(--arrow-inset);
    bottom: 32px;
    z-index: 3;
    margin: 0;
  }
}

/* Contained mode: portrait screens */
@media (max-aspect-ratio: 5/4) {
  .hero {
    /* no % here, so --stage-h can be derived from it */
    --stage-w: calc((100vw - 2 * var(--gutter)) / var(--lamps-span));
    --stage-h: calc(var(--stage-w) * 9 / 16);

    height: auto;
    min-height: var(--hero-h);
  }

  .hero__slide {
    background: var(--hero-sky);
  }

  .hero__slide::after {
    position: absolute;
    inset: 0 0 auto;
    height: calc(100% - var(--stage-h) * 0.8);
    content: '';
    background: linear-gradient(rgb(16 16 17 / var(--hero-scrim)) 60%, rgb(16 16 17 / 0%));
  }

  .hero__stage {
    top: auto;
    bottom: 0;

    /* centre the lamp group, not the photo */
    left: calc(50% - var(--stage-w) * var(--lamps-center));
    transform: none;
  }

  .hero__img {
    mask-image: linear-gradient(transparent, #000 25%);
  }

  .hero__content {
    align-self: start;

    /* room for the header on top and for the stage below; the stage's top
       8 % is sky, so the text may overlap that */
    padding-top: calc(var(--header-h) + 24px);
    padding-bottom: calc(var(--stage-h) * 0.92 + 24px);
  }
}

