  { glob: 'footer/awards/*.png' }, // ~192x86 source -> ~96x43
  { glob: 'footer/flags/*.png', display: 24 }, // 64x64 source -> 24 / 48
  { glob: 'footer/idomods.png' }, // 196x72 -> 98x36
  { glob: 'footer/idosell.png' }, // 132x72 -> 66x36
];
const SMALL_QUALITY = 90;

