  const tmp = new Uint8Array(W * H), dil = new Uint8Array(W * H);
  for (let y = 0; y < H; y++) { let run = -1e9; for (let x = 0; x < W; x++) { if (mask[y*W+x]) run = x; tmp[y*W+x] = x - run <= DILATE ? 1 : 0; } run = 1e9; for (let x = W-1; x >= 0; x--) { if (mask[y*W+x]) run = x; if (run - x <= DILATE) tmp[y*W+x] = 1; } }
  for (let x = 0; x < W; x++) { let run = -1e9; for (let y = 0; y < H; y++) { if (tmp[y*W+x]) run = y; dil[y*W+x] = y - run <= DILATE ? 1 : 0; } run = 1e9; for (let y = H-1; y >= 0; y--) { if (tmp[y*W+x]) run = y; if (run - y <= DILATE) dil[y*W+x] = 1; } }
  const hist = new Array(256).fill(0); let n = 0, sum = 0, alphaDiff = 0;
