  for (let i = 0; i < W * H; i++) {
    const o = i * 4;
    if (a[o+3] !== b[o+3]) alphaDiff++;
    const d = Math.max(Math.abs(a[o]-b[o]), Math.abs(a[o+1]-b[o+1]), Math.abs(a[o+2]-b[o+2]));
    if (dil[i]) { vis[i*3] = 40; vis[i*3+1] = 40; vis[i*3+2] = 90; continue; }
    hist[d]++; n++; sum += d;
    const v = Math.min(255, d * 8); vis[i*3] = v; vis[i*3+1] = v; vis[i*3+2] = v;
    const x = i % W, y = (i / W) | 0; const c = ((y / G) | 0) * cols + ((x / G) | 0); cell[c] += d; cellN[c]++;
  }
  const pct = (t) => (100 * hist.slice(t).reduce((s, v) => s + v, 0) / n).toFixed(3);
  const sorted = []; let acc = 0; for (let d = 0; d < 256; d++) { acc += hist[d]; sorted.push(acc); }
  const q = (p) => sorted.findIndex((v) => v >= p * n);
  console.log({ dilate: DILATE, outsidePx: n, masked: W*H-n, mean: (sum/n).toFixed(3), median: q(0.5), p99: q(0.99), p999: q(0.999), max: hist.findLastIndex((v)=>v>0), gt2: pct(3), gt5: pct(6), gt10: pct(11), gt20: pct(21), gt40: pct(41), alphaDiff });
  const worst = [...cell].map((s, i) => ({ i, m: cellN[i] ? s / cellN[i] : 0, n: cellN[i] })).filter(c => c.n > G*G/4).sort((x, y) => y.m - x.m).slice(0, 12);
  console.log('worst 120px cells (x,y in source px, mean max-channel diff):');
  for (const c of worst) console.log(((c.i % cols) * G), (((c.i / cols) | 0) * G), c.m.toFixed(2));
  await sharp(vis, { raw: { width: W, height: H, channels: 3 } }).resize(1920).png().toFile(path.join(OUT, 'diff-x8.png'));
})();
