input.code:
async (page) => {
  const S = 'C:/Users/user/AppData/Local/Temp/claude/e6cb1d3f7d8e4078/f1caf5ad-f07e-4777-8f61-c7d3f23637c0/scratchpad/clean/';
  const browser = page.context().browser();
  const out = {};
  for (const [w, h] of [[1280, 720], [1440, 900], [768, 1024], [375, 812]]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h } });
    const p = await ctx.newPage();
    const errs = []; p.on('pageerror', e => errs.push(String(e)));
    await p.goto('http://127.0.0.1:8765/index.html'); await p.waitForLoadState('load');
    const pause = await p.$('[data-slider-pause]'); if (pause) await pause.click();
    await p.waitForTimeout(1500);
    await p.screenshot({ path: S + `w${w}-s1.png` });
    const info = await p.evaluate(() => {
      const vw = document.documentElement.clientWidth;
      const hero = document.querySelector('.hero').getBoundingClientRect();
      return {
        overflow: document.documentElement.scrollWidth - vw,
        lamps: [...document.querySelectorAll('.lamp__img')].map(e => { const r = e.getBoundingClientRect(); return { op: getComputedStyle(e).opacity, inView: r.left >= -1 && r.right <= vw + 1 && r.bottom <= hero.bottom + 1 }; }),
      };
    });
    // light on all three, slide 1 then slide 2
    for (const b of await p.$$('[data-lamp]')) await b.click({ force: true });
    await p.waitForTimeout(1200);
    await p.screenshot({ path: S + `w${w}-s1-lit.png` });
    info.pool1 = await p.$eval('.light__pool', e => getComputedStyle(e).opacity);
    await p.evaluate(() => document.querySelectorAll('[data-slider-dot]')[1].click());
    await p.waitForTimeout(1500);
    info.pool2 = await p.$eval('.light__pool', e => getComputedStyle(e).opacity);
    info.lampOpS2 = await p.$$eval('.lamp__img', els => els.map(e => getComputedStyle(e).opacity).join(','));
    await p.screenshot({ path: S + `w${w}-s2-lit.png` });
    info.errs = errs;
    out[w] = info;
    await ctx.close();
  }
  return out;
}

