  await p.addInitScript(() => { try { localStorage.setItem('sollux:lamp-hint-seen', '1'); } catch (e) {} });
  await p.goto('http://127.0.0.1:8765/index.html'); await p.waitForLoadState('load');
  await p.addStyleTag({ content: 'html{scrollbar-width:none}' });
  await p.click('[data-slider-pause]');
  await p.mouse.move(960, 1500 > 1080 ? 1079 : 0); // park at the bottom centre edge first
  await p.mouse.move(1, 1200 > 0 ? 300 : 0);
  await p.mouse.move(-5, -5).catch(() => {});
  // reset: leave the page so the lamps rest
  await p.evaluate(() => document.dispatchEvent(new PointerEvent('pointerout', { pointerType: 'mouse', relatedTarget: null })));
  await p.waitForTimeout(1500);
  out.rest = await pos(p);
  await p.screenshot({ path: S + 'px-rest.png' });
  // cursor at the far top-left corner of the hero (direction (-1,-1) clamped to unit circle)
  await p.mouse.move(0, 540); // left middle -> (-1, 0)
  const samples = [];
  for (const t of [50, 150, 300, 600, 1500]) { await p.waitForTimeout(t - (samples.length ? [50,150,300,600,1500][samples.length-1] : 0)); samples.push([t, (await pos(p)).lamps[2][0]]); }
  out.followLamp3x = samples;
  out.left = await pos(p);
  await p.mouse.move(1919, 1079); // bottom-right -> (0.707, 0.707)
  await p.waitForTimeout(1500);
  out.br = await pos(p);
  // light on: glow moves with lamp
  // leave the hero (over the next section): ease back
  await p.mouse.move(960, 1079);
  await p.mouse.wheel(0, 400); await p.waitForTimeout(300);
  await p.mouse.move(960, 900);
  await p.waitForTimeout(1500);
  out.afterLeaveScrolled = (await pos(p)).inline;
  await p.mouse.wheel(0, -400); await p.waitForTimeout(400);
  await p.evaluate(() => document.dispatchEvent(new PointerEvent('pointerout', { pointerType: 'mouse', relatedTarget: null })));
  await p.waitForTimeout(1500);
  out.restAgain = await pos(p);
  await p.screenshot({ path: S + 'px-rest2.png' });
  out.errs = errs;
  await ctx.close();
  return out;
}

