  const S = 'C:/Users/user/AppData/Local/Temp/claude/e6cb1d3f7d8e4078/f1caf5ad-f07e-4777-8f61-c7d3f23637c0/scratchpad/clean/';
  const browser = page.context().browser();
  const out = {};
  const pos = (p) => p.evaluate(() => {
    const r = (el) => { const b = el.getBoundingClientRect(); return [+(b.x).toFixed(2), +(b.y).toFixed(2)]; };
    return {
      lamps: [...document.querySelectorAll('.lamp')].map(r),
      peek: [...document.querySelectorAll('.light__peek')].map(r),
      pool: [...document.querySelectorAll('.light__pool')].map(r),
