  out.followLamp3x = samples;
  out.left = await pos(p);
  await p.mouse.move(1919, 1079); // bottom-right -> (0.707, 0.707)
  await p.waitForTimeout(1500);
  out.br = await pos(p);
  // light on: glow moves with lamp
  // leave the hero (over the next section): ease back
  await p.mouse.move(960, 1079);
  await p.mouse.wheel(0, 400); await p.waitForTimeout(300);
  await p.mouse.move(960, 900);
  await p.waitForTimeout(1500);
  out.afterLeaveScrolled = (await pos(p)).inline;
  await p.mouse.wheel(0, -400); await p.waitForTimeout(400);
  await p.evaluate(() => document.dispatchEvent(new PointerEvent('pointerout', { pointerType: 'mouse', relatedTarget: null })));
  await p.waitForTimeout(1500);
