  const browser = page.context().browser();
  const out = {};
  const inline = (p) => p.evaluate(() => [...document.querySelectorAll('[data-lamp],[data-light]')].some(e => (e.getAttribute('style') || '').includes('--parallax')));
  const open = async (opts, init) => {
    const ctx = await browser.newContext(opts); const p = await ctx.newPage();
    await p.addInitScript(() => { try { localStorage.setItem('sollux:lamp-hint-seen', '1'); } catch (e) {} });
    if (init) await init(p);
    await p.goto('http://127.0.0.1:8765/index.html'); await p.waitForLoadState('load');
    await p.addStyleTag({ content: 'html{scrollbar-width:none}' });
    return [ctx, p];
  };
  // touch phone: no parallax (no hover/fine pointer). Also simulate a mouse event to be sure.
  {
    const [ctx, p] = await open({ viewport: { width: 375, height: 812 }, hasTouch: true, isMobile: true });
    await p.mouse.move(50, 600); await p.mouse.move(300, 700); await p.waitForTimeout(600);
    out.touch = await inline(p);
    await ctx.close();
  }
  // reduced motion
  {
    const [ctx, p] = await open({ viewport: { width: 1920, height: 1080 }, reducedMotion: 'reduce' });
    await p.mouse.move(10, 540); await p.mouse.move(5, 540); await p.waitForTimeout(600);
    out.reduced = await inline(p);
    await ctx.close();
  }
  // pixel identity: fresh load vs after moving and leaving; and perf with all lamps lit
  {
    const [ctx, p] = await open({ viewport: { width: 1920, height: 1080 } });
    await p.click('[data-slider-pause]'); await p.mouse.move(960, 1079); await p.mouse.move(1919, 1079);
    await p.evaluate(() => document.dispatchEvent(new PointerEvent('pointerout', { pointerType: 'mouse', relatedTarget: null })));
    await p.waitForTimeout(1200);
    await p.screenshot({ path: S + 'id-a.png' });
    for (const x of [100, 400, 1500, 1800]) { await p.mouse.move(x, 300, { steps: 5 }); }
    await p.evaluate(() => document.dispatchEvent(new PointerEvent('pointerout', { pointerType: 'mouse', relatedTarget: null })));
    await p.waitForTimeout(2000);
    await p.screenshot({ path: S + 'id-b.png' });
    // all lamps lit, cursor sweeping
    for (const b of await p.$$('[data-lamp]')) await b.click({ force: true });
    await p.waitForTimeout(1000);
    await p.evaluate(() => { window.__ft = []; let l = performance.now(); const f = (t) => { window.__ft.push(t - l); l = t; if (window.__ft.length < 240) requestAnimationFrame(f); }; requestAnimationFrame(f); });
    for (let i = 0; i < 6; i++) { await p.mouse.move(i % 2 ? 1800 : 100, i % 2 ? 900 : 150, { steps: 30 }); }
    const ft = await p.evaluate(() => window.__ft.slice(5));
    ft.sort((a, b) => a - b);
    out.frameMs = { n: ft.length, median: ft[ft.length >> 1].toFixed(1), p95: ft[Math.floor(ft.length * 0.95)].toFixed(1), max: ft[ft.length - 1].toFixed(1) };
    await p.mouse.move(100, 540, { steps: 10 }); await p.waitForTimeout(1200);
    await p.screenshot({ path: S + 'px-lit-left.png' });
    await p.mouse.move(1800, 900, { steps: 10 }); await p.waitForTimeout(1200);
    await p.screenshot({ path: S + 'px-lit-br.png' });
    await ctx.close();
  }
  return out;
}

