async (page) => {
  const browser = page.context().browser();
  const run = async (block) => {
    const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } }); const p = await ctx.newPage();
    if (block) await p.route('**/lamp-parallax.js', r => r.fulfill({ body: '', contentType: 'text/javascript' }));
    await p.addInitScript(() => { try { localStorage.setItem('sollux:lamp-hint-seen', '1'); } catch (e) {} });
    await p.goto('http://127.0.0.1:8765/index.html'); await p.waitForLoadState('load');
    await p.click('[data-slider-pause]');
    for (const b of await p.$$('[data-lamp]')) await b.click({ force: true });
    await p.waitForTimeout(1000);
    const res = [];
    for (let rep = 0; rep < 3; rep++) {
      await p.evaluate(() => { window.__ft = []; let l = performance.now(); const f = (t) => { window.__ft.push(t - l); l = t; if (window.__ft.length < 200) requestAnimationFrame(f); }; requestAnimationFrame(f); });
      for (let i = 0; i < 6; i++) await p.mouse.move(i % 2 ? 1800 : 100, i % 2 ? 900 : 150, { steps: 30 });
      const ft = (await p.evaluate(() => window.__ft.slice(5))).sort((a, b) => a - b);
      res.push([ft[ft.length >> 1].toFixed(1), ft[Math.floor(ft.length * 0.95)].toFixed(1), ft.filter(x => x > 25).length]);
    }
    await ctx.close();
    return res;
  };
  return { withParallax: await run(false), without: await run(true) };
}

