// PLAN.md §4, criterion 1: hero slider timing and controls.
// page.clock drives requestAnimationFrame and performance.now, which the
// slider's clock uses (js/hero-slider.js).
import { test, expect } from '@playwright/test';
import { openPage, activeSlide, fillScale } from './helpers.js';

test.beforeEach(async ({ page }) => {
  await page.clock.install();
  await openPage(page);
  // keep the cursor away from the controls (hover pauses autoplay)
  await page.mouse.move(960, 300);
});

test('changes slide at 3 s, with the progress bar full just before', async ({ page }) => {
  await page.clock.runFor(2900);
  expect(await activeSlide(page)).toBe(0);
  expect(await fillScale(page, 0)).toBeGreaterThan(0.95);

  await page.clock.runFor(200);
  expect(await activeSlide(page)).toBe(1);
  // the bar reset: the old segment is empty, the new one starts from 0
  expect(await fillScale(page, 0)).toBe(0);
  expect(await fillScale(page, 1)).toBeLessThan(0.05);

  await page.clock.runFor(3000);
  expect(await activeSlide(page)).toBe(0);
});

test('the crossfade is a 600 ms opacity transition', async ({ page }) => {
  await page.click('[data-slider-next]');
  const timing = await page.evaluate(async () => {
    const slide = document.querySelector('.hero__slide--active');
    const fade = slide.getAnimations().find((a) => a.transitionProperty === 'opacity');
    const endTime = fade.effect.getComputedTiming().endTime;
    await fade.finished;
    return { endTime, opacity: getComputedStyle(slide).opacity };
  });
  expect(timing.endTime).toBeLessThanOrEqual(600);
  expect(timing.opacity).toBe('1');
});

test('pauses while the mouse is over a control', async ({ page }) => {
  await page.hover('[data-slider-next]');
  await page.clock.runFor(6000);
  expect(await activeSlide(page)).toBe(0);

  await page.mouse.move(960, 300);
  await page.clock.runFor(3100);
  expect(await activeSlide(page)).toBe(1);
});

test('prev, next and the progress segments change the slide', async ({ page }) => {
  await page.click('[data-slider-next]');
  expect(await activeSlide(page)).toBe(1);
  await page.click('[data-slider-next]');
  expect(await activeSlide(page)).toBe(0);
  await page.click('[data-slider-prev]');
  expect(await activeSlide(page)).toBe(1);
  await page.locator('[data-slider-dot]').nth(0).click();
  expect(await activeSlide(page)).toBe(0);
  await expect(page.locator('[data-slider-dot]').nth(0)).toHaveAttribute('aria-current', 'true');
});

test('a manual change restarts the 3 s timer', async ({ page }) => {
  await page.clock.runFor(2000);
  await page.click('[data-slider-next]');
  await page.mouse.move(960, 300);
  await page.clock.runFor(2500);
  expect(await activeSlide(page)).toBe(1);
  await page.clock.runFor(600);
  expect(await activeSlide(page)).toBe(0);
});

test('the pause button stops and restarts autoplay', async ({ page }) => {
  const pause = page.locator('[data-slider-pause]');
  await pause.click();
  await expect(pause).toHaveAttribute('aria-pressed', 'true');
  await page.mouse.move(960, 300);
  await page.clock.runFor(6000);
  expect(await activeSlide(page)).toBe(0);

  await pause.click();
  await expect(pause).toHaveAttribute('aria-pressed', 'false');
  await page.mouse.move(960, 300);
  await page.clock.runFor(3100);
  expect(await activeSlide(page)).toBe(1);
});

// PLAN.md §4, criterion 6: the WebGL shader draws, animates, and falls back to
// the static CSS gradient without WebGL.
import { test, expect } from '@playwright/test';
import sharp from 'sharp';
import { openPage, styleOf } from './helpers.js';

/** Screenshot of the canvas alone: section background and text hidden. */
async function canvasShot(page) {
  await page.addStyleTag({
    content: '.shader { background: #000 !important; } .shader__content { visibility: hidden; }',
  });
  return page.locator('[data-shader-canvas]').screenshot({ animations: 'allow' });
}

async function stats(png) {
  const { channels } = await sharp(png).stats();
  return {
    mean: (channels[0].mean + channels[1].mean + channels[2].mean) / 3,
    stdev: (channels[0].stdev + channels[1].stdev + channels[2].stdev) / 3,
  };
}

test('the canvas has a WebGL context and draws non-blank, moving pixels', async ({ page }) => {
  await openPage(page);
  const section = page.locator('[data-shader]');
  await section.scrollIntoViewIfNeeded();
  await expect(section).toHaveClass(/shader--ready/);

  const hasContext = await page
    .locator('[data-shader-canvas]')
    .evaluate((c) => c.getContext('webgl') !== null);
  expect(hasContext).toBe(true);

  const first = await canvasShot(page);
  const s = await stats(first);
  expect(s.mean).toBeGreaterThan(10); // not black
  expect(s.stdev).toBeGreaterThan(5); // not a flat colour

  await page.waitForTimeout(1000);
  const second = await page.locator('[data-shader-canvas]').screenshot({ animations: 'allow' });
  expect(first.equals(second)).toBe(false); // animating
});

test('without WebGL the static gradient shows, with no errors', async ({ page }) => {
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
  await page.addInitScript(() => {
    const original = HTMLCanvasElement.prototype.getContext;
    HTMLCanvasElement.prototype.getContext = function (type, ...rest) {
      if (/webgl/.test(type)) return null;
      return original.call(this, type, ...rest);
    };
  });
  await openPage(page);
  const section = page.locator('[data-shader]');
  await section.scrollIntoViewIfNeeded();
  await page.waitForTimeout(500);

  await expect(section).not.toHaveClass(/shader--ready/);
  expect(await styleOf(page.locator('[data-shader-canvas]'), 'opacity')).toBe('0');
  expect(await styleOf(section, 'backgroundImage')).toMatch(/gradient/);
  expect(errors).toEqual([]);
});

// PLAN.md §4, criterion 10: prefers-reduced-motion. No autoplay, a still
// shader, and no transform transitions (opacity fades are allowed).
import { test, expect } from '@playwright/test';
import { openPage, activeSlide, styleOf } from './helpers.js';

test.beforeEach(async ({ page }) => {
  await page.emulateMedia({ reducedMotion: 'reduce' });
});

/** Running transitions/animations that move or scale something. */
const movingAnimations = (page) =>
  page.evaluate(() =>
    document
      .getAnimations()
      .filter((a) => /^(transform|scale|translate|rotate)$/.test(a.transitionProperty || ''))
      .map((a) => `${a.effect.target.className}: ${a.transitionProperty}`),
  );

test('no autoplay, and the pause button is hidden', async ({ page }) => {
  await page.clock.install();
  await openPage(page);
  await page.mouse.move(960, 300);
  await page.clock.runFor(10000);
  expect(await activeSlide(page)).toBe(0);
  await expect(page.locator('[data-slider-pause]')).toBeHidden();
});

test('a manual slide change fades without the scale-in', async ({ page }) => {
  await openPage(page);
  await page.click('[data-slider-next]');
  expect(await movingAnimations(page)).toEqual([]);
  const scales = await page
    .locator('.hero__img')
    .evaluateAll((imgs) => imgs.map((img) => getComputedStyle(img).scale));
  for (const s of scales) expect(['none', '1']).toContain(s);
});

test('tile hover does not zoom', async ({ page }) => {
  await openPage(page);
  const tile = page.locator('.tile').first();
  await tile.scrollIntoViewIfNeeded();
  await tile.hover();
  expect(await movingAnimations(page)).toEqual([]);
  await page.waitForTimeout(550);
  expect(['none', '1']).toContain(await styleOf(tile.locator('.tile__img'), 'scale'));
});

test.describe('burger menu', () => {
  test.use({ viewport: { width: 768, height: 1024 } });

  test('opens without sliding', async ({ page }) => {
    await openPage(page);
    const menu = page.locator('[data-menu]');
    const isIdentity = () =>
      menu.evaluate(
        (el) =>
          new DOMMatrixReadOnly(
            getComputedStyle(el).transform === 'none' ? undefined : getComputedStyle(el).transform,
          ).isIdentity,
      );
    expect(await isIdentity()).toBe(true);
    await page.locator('[data-menu-toggle]').click();
    expect(await movingAnimations(page)).toEqual([]);
    expect(await isIdentity()).toBe(true);
  });
});

test('the shader shows a still frame', async ({ page }) => {
  await openPage(page);
  const canvas = page.locator('[data-shader-canvas]');
  await canvas.scrollIntoViewIfNeeded();
  await page.waitForTimeout(500);
  const first = await canvas.screenshot({ animations: 'allow' });
  await page.waitForTimeout(1000);
  const second = await canvas.screenshot({ animations: 'allow' });
  expect(first.equals(second)).toBe(true);
});

// PLAN.md §4, criterion 5 and the lamp light: toggling, alignment with the
// stage, the room dim, the first-visit hint and the headline easter egg.
import { readFileSync } from 'node:fs';
import { test, expect } from '@playwright/test';
import { openPage, styleOf, box } from './helpers.js';

const POSITIONS = JSON.parse(
  readFileSync(new URL('../design/lamp-positions.json', import.meta.url), 'utf8'),
).lamps.map((l) => l.percent);

// Lamp box vs. its reference position in the stage, in CSS px (proposed;
// sub-pixel rounding only, PLAN.md §4).
const ALIGN_TOLERANCE = 1;

const DIM = { 1: 0.06, 2: 0.11, 3: 0.15 }; // --lamp-dim-1/2/3 in tokens.css

const lamp = (page, n) => page.locator(`.lamp--${n}`);
const glow = (page, n) => page.locator(`.light--${n} .light__glow`);

test.describe('switching a lamp', () => {
  test.beforeEach(async ({ page }) => {
    await openPage(page);
    await page.locator('[data-slider-pause]').click();
  });

  for (const slide of [1, 2]) {
    test(`toggles aria-pressed and the glow on slide ${slide}`, async ({ page }) => {
      if (slide === 2) await page.locator('[data-slider-dot]').nth(1).click();

      for (const n of [1, 2, 3]) {
        await expect(lamp(page, n)).toHaveAttribute('aria-pressed', 'false');
        expect(await styleOf(glow(page, n), 'opacity')).toBe('0');

        await lamp(page, n).click();
        await expect(lamp(page, n)).toHaveAttribute('aria-pressed', 'true');
        await expect.poll(() => styleOf(glow(page, n), 'opacity')).toBe('1');

        await lamp(page, n).click();
        await expect(lamp(page, n)).toHaveAttribute('aria-pressed', 'false');
        await expect.poll(() => styleOf(glow(page, n), 'opacity')).toBe('0');
      }
    });
  }

  test('works with the keyboard (Enter and Space)', async ({ page }) => {
    await lamp(page, 1).focus();
    await page.keyboard.press('Enter');
    await expect(lamp(page, 1)).toHaveAttribute('aria-pressed', 'true');
    await page.keyboard.press('Space');
    await expect(lamp(page, 1)).toHaveAttribute('aria-pressed', 'false');
  });

  test('the room dims a little more with each lamp, and not at all with none', async ({ page }) => {
    const dim = page.locator('.hero__dim');
    expect(await styleOf(dim, 'opacity')).toBe('0');
    for (const n of [1, 2, 3]) {
      await lamp(page, n).click();
      await expect.poll(async () => Number(await styleOf(dim, 'opacity'))).toBeCloseTo(DIM[n], 3);
    }
    for (const n of [1, 2, 3]) await lamp(page, n).click();
    await expect.poll(() => styleOf(dim, 'opacity')).toBe('0');
    // the blended light layer is hidden again once nothing is lit
    await page.mouse.move(960, 1000);
    await expect
      .poll(() => styleOf(page.locator('.hero__stage--light'), 'visibility'))
      .toBe('hidden');
  });

  test('all three on: "w nowym świetle" glows (easter egg)', async ({ page }) => {
    const words = page.locator('.hero__glow');
    const glowOpacity = () => styleOf(words, 'opacity', '::after');

    await lamp(page, 1).click();
    await lamp(page, 2).click();
    await page.waitForTimeout(900);
    expect(await glowOpacity()).toBe('0');

    await lamp(page, 3).click();
    await expect.poll(glowOpacity).toBe('1');
    // the heading is still read once
    await expect(page.getByRole('heading', { level: 1 })).toHaveAccessibleName(
      /^Kolor i forma\s*w nowym świetle$/,
    );

    await lamp(page, 2).click();
    await expect.poll(glowOpacity).toBe('0');
  });
});

test('the first-visit hint goes after the first click and stays gone', async ({ page }) => {
  await openPage(page, { showHint: true });
  const hint = page.locator('[data-lamp-hint]');
  await expect(hint).toBeVisible();
  await lamp(page, 2).click();
  await expect(hint).toBeHidden();

  await page.reload();
  await expect(page.locator('[data-lamp-hint]')).toBeHidden();
});

for (const [width, height] of [
  [375, 812],
  [768, 1024],
  [1440, 900],
  [1920, 1080],
]) {
  test(`lamps line up with their stage positions at ${width}`, async ({ page }) => {
    await page.setViewportSize({ width, height });
    await openPage(page);
    const stage = await box(page.locator('.hero__stage--lamps'));

    for (const [i, ref] of POSITIONS.entries()) {
      const b = await box(lamp(page, i + 1));
      expect(Math.abs(b.x - (stage.x + (ref.left / 100) * stage.width))).toBeLessThanOrEqual(
        ALIGN_TOLERANCE,
      );
      expect(Math.abs(b.y - (stage.y + (ref.top / 100) * stage.height))).toBeLessThanOrEqual(
        ALIGN_TOLERANCE,
      );
      expect(Math.abs(b.width - (ref.width / 100) * stage.width)).toBeLessThanOrEqual(
        ALIGN_TOLERANCE,
      );
    }
  });
}

test('at 375 the lamps are in view and clear of the hero text', async ({ page }) => {
  await page.setViewportSize({ width: 375, height: 812 });
  await openPage(page);
  const text = await box(page.locator('.hero__inner'));
  for (const n of [1, 2, 3]) {
    const b = await box(lamp(page, n));
    expect(b.x).toBeGreaterThanOrEqual(0);
    expect(b.x + b.width).toBeLessThanOrEqual(375);
    const overlaps =
      b.x < text.x + text.width &&
      text.x < b.x + b.width &&
      b.y < text.y + text.height &&
      text.y < b.y + b.height;
    expect(overlaps, `lamp ${n} overlaps the hero text`).toBe(false);
  }
});

// PLAN.md §4, criterion 11: on a touch device (no hover capability), tapping
// a tile or the header leaves no stuck hover state.
import { test, expect } from '@playwright/test';
import { openPage, styleOf } from './helpers.js';

test.use({ viewport: { width: 375, height: 812 }, hasTouch: true, isMobile: true });

test('the device reports no hover capability', async ({ page }) => {
  await openPage(page);
  expect(await page.evaluate(() => matchMedia('(hover: hover)').matches)).toBe(false);
});

test('tapping a tile leaves no zoom or button overlay', async ({ page }) => {
  await openPage(page);
  for (let i = 0; i < 4; i++) {
    const tile = page.locator('.tile').nth(i);
    await tile.scrollIntoViewIfNeeded();
    await tile.locator('.tile__link').tap();
    await page.waitForTimeout(600); // longer than the zoom and overlay transitions
    expect(['none', '1']).toContain(await styleOf(tile.locator('.tile__img'), 'scale'));
    expect(await styleOf(tile.locator('.button'), 'opacity', '::before')).toBe('0');
  }
});

test('tapping the header leaves it transparent', async ({ page }) => {
  await openPage(page);
  const header = page.locator('[data-header]');
  await page.locator('.header__logo').tap();
  await page.waitForTimeout(400);
  expect(await styleOf(header, 'opacity', '::before')).toBe('0');
  expect(await styleOf(header, 'color')).toBe('rgb(255, 255, 255)');
});

