.hero__dot-fill {
  position: absolute;
  inset: 21px 0;
}

.hero__dot::before {
  content: '';
  background: var(--c-track);
}

.hero__dot-fill {
  background: var(--c-yellow);
  transform: scaleX(0);
  transform-origin: left;
}

.hero__dot--active .hero__dot-fill {
  transform: scaleX(1);
}

/* Pause/play toggle (WCAG 2.2.2): styled like the bar, white icon, no
   background. Sits just right of the segments, outside the centred group, so
   the segments stay centred. 44 x 44 tap target. aria-pressed="true" means
   paused, so the icon switches to "play". */
.hero__pause {
  position: absolute;
  top: 0;
  left: calc(100% + 4px);
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  color: var(--c-white);
}

.hero__pause[hidden] {
  display: none;
}

.hero__pause[aria-pressed='true'] .hero__pause-icon--pause,
.hero__pause[aria-pressed='false'] .hero__pause-icon--play {
  display: none;
}

@media (width >= 1024px) {
  .hero__arrow {
    display: grid;
  }

  .hero__content {
    width: min(100% - 2 * var(--arrow-clear), var(--container));
  }

  .hero__badge {
    position: absolute;
    right: var(--arrow-inset);
    bottom: 32px;
    z-index: 3;
    margin: 0;
  }
}

/* Contained mode: portrait screens */
@media (max-aspect-ratio: 5/4) {
  .hero {
    /* no % here, so --stage-h can be derived from it */
    --stage-w: calc((100vw - 2 * var(--gutter)) / var(--lamps-span));
    --stage-h: calc(var(--stage-w) * 9 / 16);

    height: auto;
    min-height: var(--hero-h);
  }

  .hero__slide {
    background: var(--hero-sky);
  }

  .hero__slide::after {
    position: absolute;
    inset: 0 0 auto;
    height: calc(100% - var(--stage-h) * 0.8);
    content: '';
    background: linear-gradient(rgb(16 16 17 / var(--hero-scrim)) 60%, rgb(16 16 17 / 0%));
  }

  .hero__stage {
    top: auto;
    bottom: 0;

    /* centre the lamp group, not the photo */
    left: calc(50% - var(--stage-w) * var(--lamps-center));
    transform: none;
  }

  .hero__img {
    mask-image: linear-gradient(transparent, #000 25%);
  }

  .hero__content {
    align-self: start;

    /* room for the header on top and for the stage below; the stage's top
       8 % is sky, so the text may overlap that */
    padding-top: calc(var(--header-h) + 24px);
    padding-bottom: calc(var(--stage-h) * 0.92 + 24px);
  }
}

/* Tiles (Figma 1:631, design/figma/04-design-context-vps.tsx; PLAN.md §3.6).

   Desktop (>= 1024): two mirrored rows, 648 | 936 and 936 | 648 at 1600.
   One 3-column grid does both: 648fr 272fr 648fr with 16 px gaps gives
   648 / 16 + 272 + 16 ... = 936 exactly at 1600 and scales proportionally.
   Row height scales with the column (518 at 1600, min 360), so both tiles
   keep their image's ratio and cover only crops once the 360 px floor applies.

   Below 1024: one column, fixed height, image cropped with object-fit:
   cover (the srcset `sizes` in index.html account for that crop). */
.tiles {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 16px;
}

.tile {
  --tile-fg: var(--c-black);
  --tile-pad: clamp(24px, 2.5vw + 8px, 48px);

  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  height: clamp(440px, 60vw, 520px);
  overflow: hidden;
  color: var(--tile-fg);
  background: var(--tile-bg, var(--c-tile-stone));
  border-radius: 24px;
  isolation: isolate;
}

.tile--thoro {
  --tile-fg: var(--c-white);
  --scrim: 52%;
  --tile-pos: 40% center;
}

.tile--configurator {
  --tile-fg: var(--c-white);
  --scrim: 32%;
  --tile-bg: var(--c-tile-blue);
  --tile-pos: 85% center;
}

.tile--catalog {
  --tile-bg: var(--c-tile-cream);
  --tile-pos: 85% center;
}

.tile--smart {
  --tile-bg: var(--c-tile-stone);
  --tile-pos: 75% center;
}

/* Image zoom on hover (comments spec 05): 1 -> 1.1, 500 ms ease-out, clipped
   by the tile's overflow. `scale` is neutralised under reduced motion. */
.tile__img {
  position: absolute;
  inset: 0;
  z-index: -1;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: var(--tile-pos, center);
  /* explicit 1, not the default none: under reduced motion the hover value
     is also 1, so nothing changes and no scale transition starts */
  scale: 1;
  transition: scale var(--dur-tile) var(--ease-out);
}

.tile__body {
  display: flex;
  flex-direction: column;
  gap: 24px;
  align-items: flex-start;
  padding: var(--body-pad-top, var(--tile-pad)) var(--tile-pad) var(--tile-pad);
}

/* Contrast scrim (design/NOTES.md): white text on THORO's photo and on
   Konfigurator's blue is under WCAG minimums, so a dark gradient sits behind
   the text block only. The body grows upward by --scrim-fade; the gradient
   is clear at its top edge and reaches full strength (--scrim) 8 px above
   the eyebrow, staying there to the bottom. Strengths are the measured
   minimum for 4.5:1 on the eyebrow and 3:1 on the title at every width
   (see NOTES.md). The body is not positioned, so the link's ::after still
   covers the whole tile. */
.tile--scrim {
  --scrim-fade: 48px;
  --body-pad-top: calc(var(--tile-pad) + var(--scrim-fade));
}

.tile--scrim .tile__body {
  background: linear-gradient(
    to top,
    rgb(16 16 17 / var(--scrim)) calc(100% - var(--body-pad-top) + 8px),
    rgb(16 16 17 / 0%)
  );
}

.tile__copy {
  display: flex;
  flex-direction: column;
  gap: 12px;
  font-weight: var(--fw-bold);
  line-height: 1.1;
}

.tile__eyebrow {
  font-size: var(--fs-lead);
}

.tile__title {
  font-size: var(--fs-tile-title);
  font-weight: inherit;
  line-height: inherit;
}

/* Figma's forced line break (Konfigurator) only at desktop; narrower tiles wrap naturally */
.tile__title br {
  display: none;
}

/* One focus target: the link wraps the pill, and its ::after covers the
   whole tile (the link itself stays unpositioned). */
.tile__link {
  display: inline-flex;
  border-radius: var(--radius-pill);
}

.tile__link::after {
  position: absolute;
  inset: 0;
  content: '';
}

/* Hover anywhere on the tile: zoom + button overlay (grey). Keyboard focus
   gets the same state. */
@media (hover: hover) {
  .tile:hover .tile__img {
    scale: var(--scale-tile-hover);
  }

  .tile:hover .button::before {
    opacity: 1;
  }
}

.tile:has(.tile__link:focus-visible) .tile__img {
  scale: var(--scale-tile-hover);
}

.tile__link:focus-visible .button::before {
  opacity: 1;
}

/* Below 1024, tiles with a flat background (configurator, catalog, smart)
   stack: image block on top, text underneath on the same colour (the images'
   own background, so the join is invisible). Overlaying the text, as on
   desktop, would put it across the device mockups at these widths. THORO is
   a photo with a dark lower half and keeps the overlay. The `sizes` in
   index.html follow these boxes: wide images cover a 4:3 box at 1.355x the
   tile width, a 16:9 box at ~1.017x. */
@media (width < 1024px) {
  .tile--split {
    justify-content: flex-start;
    height: auto;
  }

  .tile--split .tile__img {
    position: static;
    z-index: auto;
    height: auto;
    aspect-ratio: 4 / 3;
  }

  /* 32 px clears the hover zoom's overhang (5 % of the image box) and,
     on Konfigurator, holds the scrim's fade on the flat colour */
  .tile--split .tile__body {
    --body-pad-top: 32px;
  }
}

@media (640px <= width < 1024px) {
  .tile--split .tile__img {
    aspect-ratio: 16 / 9;
  }
}

@media (width >= 1024px) {
  .tiles {
    grid-template-columns: 648fr 272fr 648fr;
  }

  .tile__title br {
    display: inline;
  }

  /* Row height from the column width (not aspect-ratio + min-height, which
     would force a min width and overflow the grid at 1024): narrow tile width
     (column - 32) * 0.4133, times 518/648 = 0.3304. 518 px at 1600. */
  .tile {
    height: max(360px, (min(100vw - 32px, 1600px) - 32px) * 0.3304);
  }

  /* row 1: narrow | wide; row 2: wide | narrow */
  .tile--row1.tile--wide {
    grid-column: 2 / 4;
  }

  .tile--row2.tile--wide {
    grid-column: 1 / 3;
  }

  .tile--row2.tile--narrow {
    grid-column: 3;
  }
}

/* Shader section (PLAN.md §3.7; design/frames/screen.png, 1920 x 835).
   Values are measured from the PNG (1:707 is image-only in Figma):
   heading Bold 52/1.1, letter-spacing -1 %, #f0f0f3; button Bold 18/24 with
   16/26 padding (131 x 56); subline Medium 17/1.2 in #e7e7e7. Gaps 36 / 20.

   Progressive enhancement: the section's own background is the static
   fallback (no WebGL, no JS, lost context). js/shader.js fades the canvas in
   over it once the first WebGL frame is drawn (.shader--ready). */
.shader {
  position: relative;
  display: grid;
  place-items: center;
  min-height: clamp(480px, 43.5vw, 835px);
  padding: 70px var(--gutter) 64px; /* block centre 3 px below the middle, as in the frame */
  overflow: hidden;
  color: var(--c-shader-text);
  text-align: center;
  background:
    linear-gradient(to bottom, var(--c-black) 22%, rgb(16 16 17 / 0%) 96%),
    linear-gradient(
      40deg,
      var(--c-shader-gold) 0%,
      var(--c-yellow) 11%,
      var(--c-shader-olive) 24%,
      var(--c-shader-deep) 33%,
      var(--c-shader-mid) 47%,
      var(--c-shader-olive) 60%,
      var(--c-shader-mid) 71%,
      var(--c-shader-deep) 81%,
      var(--c-shader-mid) 92%
    ),
    var(--c-black);
}

.shader__canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  transition: opacity var(--dur-fade) var(--ease);
}

.shader--ready .shader__canvas {
  opacity: 1;
}

/* Text and button are static, above the animation (comments spec 06) */
.shader__content {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.shader__title {
  max-width: 13.5em;
  font-size: var(--fs-shader);
  font-weight: var(--fw-bold);
  line-height: 1.1;
  letter-spacing: -0.01em;
}

.shader__cta {
  margin-top: 36px;
  padding-inline: 26px;
  font-size: var(--fs-18);
  line-height: 24px;
}

.shader__note {
  max-width: 15em;
  margin-top: 20px;
  font-size: var(--fs-17);
  font-weight: var(--fw-medium);
  line-height: 1.2;
  color: var(--c-line);
}

