// Worst-case WCAG contrast of each hero/header text element on a slide.
// Text is made transparent, the area behind each element's text box is
// screenshotted, and the text colour is compared with every pixel there.
import { chromium } from '@playwright/test';
import sharp from 'sharp';
const slide = Number(process.argv[2] ?? 1);
const lum = ([r, g, b]) => { const f = (v) => { v /= 255; return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; }; return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b); };
const ratio = (a, b) => { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); };
const SEL = [
  ['logo', '.header__logo svg'], ['nav links', '.header__link'], ['search text', '.search__input'],
  ['configurator', '.header__configurator'], ['account icon', '.header__icon--user svg'], ['cart icon', '.header__actions .header__icon svg'],
  ['eyebrow', '.hero__eyebrow'], ['H1', '.hero__title'], ['CTA', '.hero__cta'], ['badge 4.8', '.hero__rating'], ['badge label', '.hero__badge > span:last-child'],
];
const browser = await chromium.launch();
for (const [w, h] of [[1280, 633], [1920, 1080]]) {
  const page = await browser.newPage({ viewport: { width: w, height: h } });
  await page.addInitScript(() => localStorage.setItem('sollux:lamp-hint-seen', '1'));
  await page.goto('http://127.0.0.1:8765/index.html'); await page.evaluate(() => document.fonts.ready);
  await page.locator('[data-slider-pause]').click();
  if (slide === 2) await page.locator('[data-slider-dot]').nth(1).click();
  await page.mouse.move(w / 2, h - 2); await page.waitForTimeout(1500);
  const info = await page.evaluate((sel) => sel.map(([name, s]) => {
    const els = [...document.querySelectorAll(s)].filter((e) => e.getClientRects().length);
    return { name, items: els.map((e) => { const r = e.getBoundingClientRect(); const cs = getComputedStyle(e);
      return { x: r.x, y: r.y, w: r.width, h: r.height, color: cs.color, size: parseFloat(cs.fontSize), weight: Number(cs.fontWeight) }; }) };
  }), SEL);
  await page.addStyleTag({ content: '.header *, .hero__content *, .header { color: transparent !important; text-shadow: none !important; } .search { border-color: transparent !important; } .search__input::placeholder { color: transparent !important; }' });
  await page.waitForTimeout(400);
  const png = await page.screenshot();
  const { data, info: im } = await sharp(png).raw().toBuffer({ resolveWithObject: true });
  console.log(`\n== slide ${slide} at ${w}x${h}`);
  for (const { name, items } of info) {
    let worst = Infinity, fg, large;
    for (const it of items) {
      fg = it.color.match(/\d+/g).slice(0, 3).map(Number);
      large = name.includes('icon') || name === 'logo' ? 'graphic' : it.size >= 24 || (it.size >= 18.66 && it.weight >= 700) ? 'large' : 'small';
      for (let y = Math.max(0, Math.floor(it.y)); y < Math.min(im.height, Math.ceil(it.y + it.h)); y++)
        for (let x = Math.max(0, Math.floor(it.x)); x < Math.min(im.width, Math.ceil(it.x + it.w)); x++) {
          const i = (y * im.width + x) * im.channels; worst = Math.min(worst, ratio(fg, [data[i], data[i + 1], data[i + 2]]));
        }
    }
    const need = large === 'small' ? 4.5 : 3;
    console.log(`${name.padEnd(14)} ${large.padEnd(7)} need ${need}  worst ${worst.toFixed(2)}  ${worst >= need ? 'ok' : 'FAIL'}`);
  }
  await page.close();
}
await browser.close();
EOF
