     1	// PLAN.md §4, criteria 2 and 4: header hover and the burger menu.
     2	import { test, expect } from '@playwright/test';
     3	import { openPage, styleOf } from './helpers.js';
     4	
     5	const INK = 'rgb(30, 30, 30)'; // --c-ink
     6	const WHITE = 'rgb(255, 255, 255)';
     7	
     8	test.describe('hover (desktop)', () => {
     9	  test('turns solid after 250 ms and reverts on leave', async ({ page }) => {
    10	    await openPage(page);
    11	    const header = page.locator('[data-header]');
    12	    expect(await styleOf(header, 'color')).toBe(WHITE);
    13	    expect(await styleOf(header, 'opacity', '::before')).toBe('0');
    14	
    15	    await page.hover('.header__logo');
    16	    await page.waitForTimeout(300); // --dur-hover 250 ms + a frame
    17	    expect(await styleOf(header, 'color')).toBe(INK);
    18	    expect(await styleOf(header, 'opacity', '::before')).toBe('1');
    19	
    20	    await page.mouse.move(960, 600);
    21	    await page.waitForTimeout(300);
    22	    expect(await styleOf(header, 'color')).toBe(WHITE);
    23	    expect(await styleOf(header, 'opacity', '::before')).toBe('0');
    24	  });
    25	});
    26	
    27	test.describe('burger menu (< 1280 px)', () => {
    28	  test.use({ viewport: { width: 768, height: 1024 } });
    29	
    30	  test.beforeEach(async ({ page }) => {
    31	    await openPage(page);
    32	  });
    33	
    34	  test('opens and closes, with aria-expanded', async ({ page }) => {
    35	    const burger = page.locator('[data-menu-toggle]');
    36	    const menu = page.locator('[data-menu]');
    37	    await expect(burger).toHaveAttribute('aria-expanded', 'false');
    38	    await expect(menu).toBeHidden();
    39	
    40	    await burger.click();
    41	    await expect(burger).toHaveAttribute('aria-expanded', 'true');
    42	    await expect(menu).toBeVisible();
    43	    await expect(page.locator('main')).toHaveJSProperty('inert', true);
    44	
    45	    await burger.click();
    46	    await expect(burger).toHaveAttribute('aria-expanded', 'false');
    47	    await expect(menu).toBeHidden();
    48	    await expect(page.locator('main')).toHaveJSProperty('inert', false);
    49	  });
    50	
    51	  test('Esc closes it and focus returns to the burger', async ({ page }) => {
    52	    const burger = page.locator('[data-menu-toggle]');
    53	    await burger.click();
    54	    await expect(burger).toHaveAttribute('aria-expanded', 'true');
    55	    await page.keyboard.press('Escape');
    56	    await expect(burger).toHaveAttribute('aria-expanded', 'false');
    57	    await expect(burger).toBeFocused();
    58	  });
    59	
    60	  test('focus is trapped in the header while open', async ({ page }) => {
    61	    await page.locator('[data-menu-toggle]').click();
    62	    const inHeader = () =>
    63	      page.evaluate(() => document.querySelector('[data-header]').contains(document.activeElement));
    64	
    65	    for (let i = 0; i < 25; i++) {
    66	      await page.keyboard.press('Tab');
    67	      expect(await inHeader()).toBe(true);
    68	    }
    69	    for (let i = 0; i < 25; i++) {
    70	      await page.keyboard.press('Shift+Tab');
    71	      expect(await inHeader()).toBe(true);
    72	    }
    73	  });
    74	});
    75	// Shared helpers for the spec files.
    76	
    77	/** Load the page. The first-visit lamp hint is marked as seen unless asked. */
    78	export async function openPage(page, { showHint = false } = {}) {
    79	  if (!showHint) {
    80	    await page.addInitScript(() => {
    81	      try {
    82	        window.localStorage.setItem('sollux:lamp-hint-seen', '1');
    83	      } catch {
    84	        // storage blocked: the hint just shows
    85	      }
    86	    });
    87	  }
    88	  await page.goto('index.html');
    89	}
    90	
    91	/** A computed style value, optionally of a pseudo-element. */
    92	export function styleOf(locator, property, pseudo = null) {
    93	  return locator.evaluate(
    94	    (el, [prop, pseudoEl]) => getComputedStyle(el, pseudoEl)[prop],
    95	    [property, pseudo],
    96	  );
    97	}
    98	
    99	/** Bounding box in CSS px (rounded to 0.01). */
   100	export async function box(locator) {
   101	  const b = await locator.boundingBox();
   102	  const r = (n) => Math.round(n * 100) / 100;
   103	  return { x: r(b.x), y: r(b.y), width: r(b.width), height: r(b.height) };
   104	}
   105	
   106	/** Index of the active hero slide. */
   107	export function activeSlide(page) {
   108	  return page.evaluate(() =>
   109	    [...document.querySelectorAll('[data-slide]')].findIndex((s) =>
   110	      s.classList.contains('hero__slide--active'),
   111	    ),
   112	  );
   113	}
   114	
   115	/** The x scale of a progress segment's fill (1 = full). */
   116	export function fillScale(page, index) {
   117	  return page.evaluate((i) => {
   118	    const fill = document.querySelectorAll('[data-slider-dot]')[i].firstElementChild;
   119	    const transform = getComputedStyle(fill).transform;
   120	    return transform === 'none' ? 1 : new DOMMatrixReadOnly(transform).a;
   121	  }, index);
   122	}
