// Convex hull of each lamp's visible pixels, in % of the image, rounded outward.
import sharp from 'sharp';
const GRID = 60; // cells per side; a cell counts if any pixel in it has alpha > 0
for (const n of [1, 2, 3]) {
  const { data, info } = await sharp(`assets/img/lamp${n}@2x.webp`).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const { width: W, height: H, channels: C } = info;
  const pts = new Set();
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    if (data[(y * W + x) * C + 3] === 0) continue;
    const cx = Math.floor((x / W) * GRID), cy = Math.floor((y / H) * GRID);
    for (const [dx, dy] of [[0, 0], [1, 0], [0, 1], [1, 1]]) pts.add(`${cx + dx},${cy + dy}`);
  }
  const P = [...pts].map((s) => s.split(',').map(Number)).sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const cross = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lower = [], upper = [];
  for (const p of P) { while (lower.length >= 2 && cross(lower.at(-2), lower.at(-1), p) <= 0) lower.pop(); lower.push(p); }
  for (const p of [...P].reverse()) { while (upper.length >= 2 && cross(upper.at(-2), upper.at(-1), p) <= 0) upper.pop(); upper.push(p); }
  const hull = [...lower.slice(0, -1), ...upper.slice(0, -1)];
  const pct = (v) => +((v / GRID) * 100).toFixed(2);
  console.log(`lamp${n} (${W}x${H}) ${hull.length} pts: polygon(${hull.map(([x, y]) => `${pct(x)}% ${pct(y)}%`).join(', ')})`);
}
EOF
