cd "C:/Users/user/OneDrive/Документы/idomods-task" && S="C:/Users/user/AppData/Local/Temp/claude/e6cb1d3f7d8e4078/f1caf5ad-f07e-4777-8f61-c7d3f23637c0/scratchpad" && cat > "$S/ring.mjs" <<'EOF'
// Contrast of hero/header text against what is right around its letters.
// A = page as is; B = same, text colour transparent (shadows kept);
// glyph mask = where A and B differ; ring = pixels within R px of a glyph,
// outside it. Contrast: text colour vs the worst ring pixel in B. Also the
// line-box worst pixel (text and shadow both hidden), as measured before.
import { chromium } from '@playwright/test';
import sharp from 'sharp';
const [slide, sizesArg, R = 2] = [Number(process.argv[2]), process.argv[3] ?? '1280x633,1920x1080', Number(process.argv[4] ?? 2)];
const lin = (v) => { v /= 255; return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; };
const lum = (r, g, b) => 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
const ratio = (a, b) => (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
const SEL = [['nav links', '.header__link'], ['search text', '.search__input'], ['configurator', '.header__configurator-label'],
  ['eyebrow', '.hero__eyebrow'], ['H1', '.hero__title'], ['H1 "świetle"', '.hero__glow'], ['badge label', '.hero__badge > span:last-child']];
const HIDE = '.header *, .hero__content *, .header { color: transparent !important; } .search__input::placeholder { color: transparent !important; }';
const browser = await chromium.launch();
const raw = async (page) => sharp(await page.screenshot()).raw().toBuffer({ resolveWithObject: true });
for (const [w, h] of sizesArg.split(',').map((s) => s.split('x').map(Number))) {
  const page = await browser.newPage({ viewport: { width: w, height: h } });
  await page.addInitScript(() => localStorage.setItem('sollux:lamp-hint-seen', '1'));
  await page.goto('http://127.0.0.1:8765/index.html'); await page.evaluate(() => document.fonts.ready);
  const pause = page.locator('[data-slider-pause]'); if (await pause.isVisible()) await pause.click();
  if (slide === 2) await page.locator('[data-slider-dot]').nth(1).click();
  await page.mouse.move(w / 2, h - 2); await page.waitForTimeout(1500);
  const info = await page.evaluate((sel) => sel.map(([name, s]) => {
    const items = [];
    for (const e of document.querySelectorAll(s)) { if (!e.getClientRects().length) continue;
      const cs = getComputedStyle(e); const fg = cs.color.match(/\d+/g).slice(0, 3).map(Number);
      if (e.matches('input')) { const r = e.getBoundingClientRect(); const c = document.createElement('canvas').getContext('2d'); c.font = cs.font;
        const lh = parseFloat(cs.fontSize) * 1.2; items.push({ x: r.x + parseFloat(cs.paddingLeft), y: r.y + (r.height - lh) / 2, w: c.measureText(e.placeholder).width, h: lh, fg, size: parseFloat(cs.fontSize), weight: +cs.fontWeight }); continue; }
      const wk = document.createTreeWalker(e, NodeFilter.SHOW_TEXT);
      for (let n; (n = wk.nextNode()); ) { if (!n.textContent.trim()) continue; const t = getComputedStyle(n.parentElement); const rg = document.createRange(); rg.selectNodeContents(n);
        for (const r of rg.getClientRects()) items.push({ x: r.x, y: r.y, w: r.width, h: r.height, fg, size: parseFloat(t.fontSize), weight: +t.fontWeight }); } }
    return { name, items };
  }), SEL);
  const A = await raw(page);
  const tagB = await page.addStyleTag({ content: HIDE });
  await page.waitForTimeout(300); const B = await raw(page);
  await page.addStyleTag({ content: '.header *, .hero__content *, .header { text-shadow: none !important; } .search { border-color: transparent !important; }' + ' .hero__glow::after { display: none !important; }' });
  await page.waitForTimeout(300); const C = await raw(page);
  const W = A.info.width, H = A.info.height, ch = A.info.channels;
  console.log(`\n== slide ${slide} ${w}x${h}  (ring = ${R} px around the letters)`);
  for (const { name, items } of info) {
    if (!items.length) { console.log(`${name.padEnd(16)} (not shown)`); continue; }
    const large = items.some((i) => i.size >= 24 || (i.size >= 18.66 && i.weight >= 700)); const need = large ? 3 : 4.5;
    const lf = lum(...items[0].fg);
    let ring = Infinity, box = Infinity;
    for (const it of items) {
      const x0 = Math.max(0, Math.floor(it.x) - R), x1 = Math.min(W, Math.ceil(it.x + it.w) + R), y0 = Math.max(0, Math.floor(it.y) - R), y1 = Math.min(H, Math.ceil(it.y + it.h) + R);
      const bw = x1 - x0, bh = y1 - y0, mask = new Uint8Array(bw * bh);
      for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) { const i = (y * W + x) * ch;
        if (Math.abs(A.data[i] - B.data[i]) + Math.abs(A.data[i + 1] - B.data[i + 1]) + Math.abs(A.data[i + 2] - B.data[i + 2]) > 24) mask[(y - y0) * bw + (x - x0)] = 1; }
      for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) {
        const k = (y - y0) * bw + (x - x0), i = (y * W + x) * ch;
        if (y >= it.y && y < it.y + it.h && x >= it.x && x < it.x + it.w) box = Math.min(box, ratio(lf, lum(C.data[i], C.data[i + 1], C.data[i + 2])));
        if (mask[k]) continue; let near = false;
        for (let dy = -R; dy <= R && !near; dy++) for (let dx = -R; dx <= R; dx++) { const yy = y - y0 + dy, xx = x - x0 + dx; if (yy >= 0 && yy < bh && xx >= 0 && xx < bw && mask[yy * bw + xx]) { near = true; break; } }
        if (near) ring = Math.min(ring, ratio(lf, lum(B.data[i], B.data[i + 1], B.data[i + 2])));
      }
    }
    console.log(`${name.padEnd(16)} ${large ? 'large' : 'small'} need ${need}  ring ${ring.toFixed(2)} ${ring >= need ? 'ok  ' : 'FAIL'}  line box ${box.toFixed(2)}`);
  }
  await page.close();
}
await browser.close();
EOF
