cd "C:/Users/user/OneDrive/Документы/idomods-task" && OUT="C:/Users/user/AppData/Local/Temp/claude/e6cb1d3f7d8e4078/f1caf5ad-f07e-4777-8f61-c7d3f23637c0/scratchpad/shadow-compare" && mkdir -p "$OUT" && cat > scripts/_cmp.mjs <<'EOF'
import { chromium } from '@playwright/test';
import sharp from 'sharp';
const out = process.argv[2];
const K = 'color-mix(in srgb, var(--c-black) ';
const V = {
  none: 'none',
  subtle: `0 0 2px ${K}70%, transparent), 0 0 12px ${K}35%, transparent)`,
  heavy: `0 0 2px ${K}80%, transparent), 0 0 4px ${K}60%, transparent), 0 0 4px ${K}60%, transparent), 0 0 12px ${K}35%, transparent)`,
};
const b = await chromium.launch();
const crops = [];
for (const [name, sh] of Object.entries(V)) {
  const p = await b.newPage({ viewport: { width: 1280, height: 633 }, deviceScaleFactor: 2 });
  await p.addInitScript(() => localStorage.setItem('sollux:lamp-hint-seen', '1'));
  await p.goto('http://127.0.0.1:8765/index.html'); await p.evaluate(() => document.fonts.ready);
  await p.addStyleTag({ content: `:root { --text-shadow-hero: ${sh} !important; }` });
  await p.locator('[data-slider-pause]').click(); await p.mouse.move(640, 630); await p.waitForTimeout(1200);
  const f = `${out}/crop-${name}.png`;
  await p.screenshot({ path: f, clip: { x: 130, y: 10, width: 640, height: 350 } });
  crops.push(f); await p.close();
}
await b.close();
// stack the three crops vertically with labels-free gaps
const imgs = await Promise.all(crops.map((f) => sharp(f).toBuffer({ resolveWithObject: true })));
const W = imgs[0].info.width, H = imgs[0].info.height, gap = 12;
await sharp({ create: { width: W, height: H * 3 + gap * 2, channels: 3, background: '#ffffff' } })
  .composite(imgs.map((im, i) => ({ input: im.data, top: i * (H + gap), left: 0 })))
  .png().toFile(`${out}/compare-none-subtle-heavy-1280.png`);
EOF
node scripts/_cmp.mjs "$OUT"; rm scripts/_cmp.mjs; ls "$OUT"

